  void initCast(){try{castSelector=new MediaRouteSelector.Builder().addControlCategory(CastMediaControlIntent.categoryForCast(CastMediaControlIntent.DEFAULT_MEDIA_RECEIVER_APPLICATION_ID)).build();mediaRouter=MediaRouter.getInstance(this);castRouteCallback=new MediaRouter.Callback(){@Override public void onRouteAdded(MediaRouter router,MediaRouter.RouteInfo route){if("cast".equals(page))scanTvOutputs(false);}@Override public void onRouteChanged(MediaRouter router,MediaRouter.RouteInfo route){if("cast".equals(page))scanTvOutputs(false);}@Override public void onRouteRemoved(MediaRouter router,MediaRouter.RouteInfo route){if("cast".equals(page))scanTvOutputs(false);}};mediaRouter.addCallback(castSelector,castRouteCallback,MediaRouter.CALLBACK_FLAG_REQUEST_DISCOVERY);}catch(Exception e){castSelector=null;mediaRouter=null;}try{castContext=CastContext.getSharedInstance(this);castSessionListener=new SessionManagerListener<CastSession>(){public void onSessionStarting(CastSession s){updateCastStatus("Conectando…");}public void onSessionStarted(CastSession s,String id){activeTvMethod="CAST";updateCastStatus("Conectado a "+castDeviceName(s));castCurrentToSession(s);updateTvButton();updateNowBar();scanTvOutputs(false);}public void onSessionStartFailed(CastSession s,int error){updateCastStatus("No se pudo conectar · "+error);}public void onSessionEnding(CastSession s){updateCastStatus("Desconectando…");}public void onSessionEnded(CastSession s,int error){if("CAST".equals(activeTvMethod)){activeTvMethod="";activeTvTarget=null;}updateCastStatus("Sin dispositivo conectado");updateTvButton();updateNowBar();if(player!=null&&current!=null)player.play();scanTvOutputs(false);}public void onSessionResuming(CastSession s,String id){updateCastStatus("Reconectando…");}public void onSessionResumed(CastSession s,boolean wasSuspended){updateCastStatus("Conectado a "+castDeviceName(s));}public void onSessionResumeFailed(CastSession s,int error){updateCastStatus("No se pudo reconectar");}public void onSessionSuspended(CastSession s,int reason){updateCastStatus("Conexión suspendida");}};castContext.getSessionManager().addSessionManagerListener(castSessionListener,CastSession.class);}catch(Exception e){castContext=null;}}

  String castDeviceName(CastSession s){try{return s!=null&&s.getCastDevice()!=null?s.getCastDevice().getFriendlyName():"TV";}catch(Exception e){return "TV";}}
  void updateCastStatus(String s){if(castStatus!=null)castStatus.setText(s);}
  String castContentType(String url){String u=url==null?"":url.toLowerCase(Locale.ROOT);if(u.contains(".mp4"))return "video/mp4";if(u.contains(".ts")||u.contains("output=ts"))return "video/mp2t";return "application/x-mpegURL";}
  boolean castConnected(){CastSession s=currentCastSession();try{return s!=null&&s.isConnected();}catch(Throwable e){return false;}}
  void castCurrentIfConnected(){if(current==null)return;CastSession s=currentCastSession();if(s==null)return;castCurrentToSession(s);}
  void castCurrentToSession(CastSession s){if(s==null||current==null)return;try{RemoteMediaClient client=s.getRemoteMediaClient();if(client==null)return;com.google.android.gms.cast.MediaMetadata md=new com.google.android.gms.cast.MediaMetadata(com.google.android.gms.cast.MediaMetadata.MEDIA_TYPE_GENERIC);md.putString(com.google.android.gms.cast.MediaMetadata.KEY_TITLE,current.name);md.putString(com.google.android.gms.cast.MediaMetadata.KEY_SUBTITLE,cleanGroup(current.group));if(current.logo!=null&&!current.logo.isEmpty())md.addImage(new WebImage(Uri.parse(current.logo)));com.google.android.gms.cast.MediaInfo info=new com.google.android.gms.cast.MediaInfo.Builder(current.url).setStreamType(com.google.android.gms.cast.MediaInfo.STREAM_TYPE_LIVE).setContentType(castContentType(current.url)).setMetadata(md).build();com.google.android.gms.cast.MediaLoadRequestData req=new com.google.android.gms.cast.MediaLoadRequestData.Builder().setMediaInfo(info).setAutoplay(true).build();client.load(req);if(player!=null)player.pause();updateCastStatus("Enviando "+current.name+" a "+castDeviceName(s));}catch(Exception e){updateCastStatus("Error al enviar canal");toast("No se pudo enviar este canal al dispositivo Cast");}}
  void openCastChooser(){try{if(!ensureCastReady()){toast("Google Cast no está disponible en este teléfono");return;}MediaRouteChooserDialog dlg=new MediaRouteChooserDialog(this);dlg.setRouteSelector(castSelector);dlg.setTitle("Dispositivos Google Cast");dlg.show();}catch(Throwable e){updateCastStatus("Google Cast no disponible");toast("Cast no pudo abrirse: "+e.getClass().getSimpleName());}}

  boolean hasValidatedInternet(){try{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();NetworkCapabilities x=n==null?null:cm.getNetworkCapabilities(n);return x!=null&&x.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&x.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);}catch(Exception e){return networkConnected();}}
  boolean hasLocalNetwork(){try{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();NetworkCapabilities x=n==null?null:cm.getNetworkCapabilities(n);return x!=null&&(x.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||x.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET));}catch(Exception e){return networkConnected();}}
  boolean systemWirelessDisplayAvailable(){try{return new Intent(android.provider.Settings.ACTION_CAST_SETTINGS).resolveActivity(getPackageManager())!=null;}catch(Exception e){return false;}}
  boolean currentDirectFriendly(){return current==null||TvOutputUtil.directStreamFriendly(current.url);}
  boolean currentDlnaFriendly(){return current==null||TvOutputUtil.dlnaStreamFriendly(current.url);}
  CastSession currentCastSession(){try{if(castContext==null||castContext.getSessionManager()==null)return null;return castContext.getSessionManager().getCurrentCastSession();}catch(Throwable e){return null;}}
  boolean ensureCastReady(){if(castContext!=null&&castSelector!=null&&mediaRouter!=null)return true;initCast();return castContext!=null&&castSelector!=null&&mediaRouter!=null;}

  String activeTvName(){if(castConnected())return castDeviceName(currentCastSession());if(activeTvTarget!=null&&activeTvTarget.name!=null&&!activeTvTarget.name.isEmpty())return activeTvTarget.name;return "TV / Proyector";}
  boolean tvActuallyConnected(){return castConnected()||"DLNA".equals(activeTvMethod);}
  void updateTvButton(){if(sendTvButton==null)return;if(tvActuallyConnected()){sendTvButton.setText("✓ Conectado · "+activeTvName());sendTvButton.setBackground(buttonBg(Color.rgb(17,105,77),Color.rgb(24,135,98),14));}else{sendTvButton.setText("Enviar a TV / Proyector");sendTvButton.setBackground(buttonBg(PV_PRIMARY,Color.rgb(20,132,255),14));}}
  void disconnectRemoteOnly(){++autoConnectGeneration;String method=activeTvMethod==null?"":activeTvMethod;TvTarget target=activeTvTarget;if("CAST".equals(method)||castConnected()){try{CastSession s=currentCastSession();if(s!=null&&s.getRemoteMediaClient()!=null)try{s.getRemoteMediaClient().stop();}catch(Throwable ignored){}if(castContext!=null&&castContext.getSessionManager()!=null)castContext.getSessionManager().endCurrentSession(true);}catch(Throwable ignored){}activeTvMethod="";activeTvTarget=null;if(player!=null&&current!=null)player.play();updateTvButton();updateNowBar();toast("TV desconectado");return;}if("DLNA".equals(method)&&target!=null&&!target.controlUrl.isEmpty()){activeTvMethod="";activeTvTarget=null;tvIo.submit(()->{try{dlnaSoap(target.controlUrl,target.serviceType,"Stop","<InstanceID>0</InstanceID>");}catch(Exception ignored){}mainHandler.post(()->{if(player!=null&&current!=null)player.play();updateTvButton();updateNowBar();toast("TV desconectado");});});return;}activeTvMethod="";activeTvTarget=null;updateTvButton();updateNowBar();}
  void openTvOutputFromPlayer(){if(current==null){toast("Selecciona primero un canal para enviarlo al TV o proyector");return;}if(tvActuallyConnected()){String[] opts={"Cambiar dispositivo","Desconectar del TV"};AlertDialog d=new AlertDialog.Builder(this).setTitle("✓ Conectado a "+activeTvName()).setItems(opts,(x,w)->{if(w==0)showCastScreen();else disconnectRemoteOnly();}).setNegativeButton("Cerrar",null).create();styleDialog(d);return;}showCastScreen();}

  void showCastScreen(){setPage("cast","Enviar a TV");LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(10),dp(8),dp(10),dp(10));p.setBackground(outlinePanel());contentFrame.addView(p,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("Enviar a TV / Proyector",22,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);p.addView(h,new LinearLayout.LayoutParams(-1,dp(38)));CastSession activeCast=currentCastSession();castStatus=tv(activeCast!=null&&castConnected()?"Conectado a "+castDeviceName(activeCast):"Selecciona un dispositivo",12,activeCast!=null&&castConnected()?GREEN:MUTED);p.addView(castStatus,new LinearLayout.LayoutParams(-1,dp(30)));tvAnalysisStatus=tv("Buscando TV y proyectores…",12,CYAN);tvAnalysisStatus.setPadding(dp(10),dp(4),dp(10),dp(4));tvAnalysisStatus.setBackground(rounded(PV_SURFACE_2,12));p.addView(tvAnalysisStatus,new LinearLayout.LayoutParams(-1,dp(50)));LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);Button refresh=iconBtn("Buscar de nuevo",R.drawable.pv_ic_refresh),wifi=iconBtn("Cambiar Wi-Fi",R.drawable.pv_ic_globe);actions.addView(refresh,weight());actions.addView(wifi,weight());p.addView(actions,new LinearLayout.LayoutParams(-1,dp(56)));TextView label=tv("Dispositivos encontrados",13,Color.WHITE);label.setTypeface(Typeface.DEFAULT,Typeface.BOLD);label.setPadding(dp(6),dp(4),0,0);p.addView(label,new LinearLayout.LayoutParams(-1,dp(32)));ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);tvResults=new LinearLayout(this);tvResults.setOrientation(LinearLayout.VERTICAL);scroll.addView(tvResults,new ScrollView.LayoutParams(-1,-2));p.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));refresh.setOnClickListener(v->scanTvOutputs(true));wifi.setOnClickListener(v->openWifiPanel());scanTvOutputs(true);}

  void openWifiPanel(){try{if(Build.VERSION.SDK_INT>=29)startActivity(new Intent(android.provider.Settings.Panel.ACTION_WIFI));else startActivity(new Intent(android.provider.Settings.ACTION_WIFI_SETTINGS));}catch(Exception e){try{startActivity(new Intent(android.provider.Settings.ACTION_WIFI_SETTINGS));}catch(Exception ignored){toast("No se pudo abrir el selector Wi-Fi");}}}
  void openWirelessDisplay(){try{startActivity(new Intent(android.provider.Settings.ACTION_CAST_SETTINGS));}catch(Exception e){toast("Este teléfono no expone pantalla inalámbrica desde Android");}}

  String normalizeDeviceName(String name){if(name==null)return "";return name.toLowerCase(Locale.ROOT).replaceAll("\\([^)]*\\)"," ").replaceAll("\\b(tv|television|televisor|chromecast|google cast|smart)\\b"," ").replaceAll("[^a-z0-9]+"," ").trim().replaceAll("\\s+"," ");}
  String devicePrefKey(TvDevice d){return "tv_method_"+sha1(normalizeDeviceName(d.name));}

  void scanTvOutputs(boolean dlna){final long gen=++tvScanGeneration;autoConnectGeneration++;final boolean internet=hasValidatedInternet(),local=hasLocalNetwork(),castFriendly=currentDirectFriendly(),dlnaFriendly=currentDlnaFriendly();synchronized(tvTargets){tvTargets.clear();if(ensureCastReady())collectCastTargets(internet,local,castFriendly);}rebuildTvDevices();renderTvDevices(internet,local,dlna?"Buscando dispositivos en la red…":"Búsqueda actualizada");if(dlna&&local)discoverDlna(gen,internet,local,dlnaFriendly);else if(dlna&&!local)renderTvDevices(internet,local,"Conecta el teléfono a Wi-Fi para buscar Smart TV");}
  void collectCastTargets(boolean internet,boolean local,boolean friendly){if(mediaRouter==null||castSelector==null)return;try{for(MediaRouter.RouteInfo route:mediaRouter.getRoutes()){if(route==null||!route.matchesSelector(castSelector)||route.isDefault())continue;String name=String.valueOf(route.getName());tvTargets.add(new TvTarget("CAST",name,"Receptor detectado",TvOutputUtil.score("CAST",internet,local,friendly,true),"","",route.getId(),true));}}catch(Throwable ignored){}}

  void rebuildTvDevices(){LinkedHashMap<String,TvDevice> map=new LinkedHashMap<>();synchronized(tvTargets){for(TvTarget t:tvTargets){if(!t.actual)continue;String key=normalizeDeviceName(t.name);if(key.isEmpty())key=t.name.toLowerCase(Locale.ROOT);TvDevice d=map.get(key);if(d==null){d=new TvDevice(t.name);map.put(key,d);}d.add(t);}}ArrayList<TvDevice> list=new ArrayList<>(map.values());for(TvDevice d:list)d.refreshScore();Collections.sort(list,(a,b)->Integer.compare(b.score,a.score));synchronized(tvDevices){tvDevices.clear();tvDevices.addAll(list);}}
  void renderTvDevices(boolean internet,boolean local,String state){if(!"cast".equals(page)||tvResults==null)return;ArrayList<TvDevice> data; synchronized(tvDevices){data=new ArrayList<>(tvDevices);}tvResults.removeAllViews();String network=(internet?"Internet disponible":"Sin Internet validado")+" · "+(local?"Red local activa":"Sin red local");if(tvAnalysisStatus!=null)tvAnalysisStatus.setText(state+"\n"+network);int rank=1;for(TvDevice d:data){final int pos=rank++;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(8),dp(12),dp(8));card.setBackground(glassCard());TextView top=tv("#"+pos+" · "+d.name,14,pos==1?GREEN:Color.WHITE);top.setTypeface(Typeface.DEFAULT,Typeface.BOLD);top.setSingleLine(true);top.setEllipsize(android.text.TextUtils.TruncateAt.END);TextView sub=tv((pos==1?"Recomendado · ":"")+"Conexión automática",11,CYAN);TextView why=tv("PalmaVision probará automáticamente las opciones disponibles hasta conectarse.",11,MUTED);why.setMaxLines(2);Button connect=primaryIconBtn("Conectar",R.drawable.pv_ic_cast);connect.setTextSize(12);card.addView(top,new LinearLayout.LayoutParams(-1,dp(30)));card.addView(sub,new LinearLayout.LayoutParams(-1,dp(24)));card.addView(why,new LinearLayout.LayoutParams(-1,dp(42)));card.addView(connect,new LinearLayout.LayoutParams(-1,dp(46)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(150));cp.setMargins(0,dp(5),0,dp(5));tvResults.addView(card,cp);connect.setOnClickListener(v->startAutoConnect(d));}if(data.isEmpty()){TextView empty=tv("Todavía no se detectan TV o proyectores directos.",13,MUTED);empty.setGravity(Gravity.CENTER);tvResults.addView(empty,new LinearLayout.LayoutParams(-1,dp(72)));}if(systemWirelessDisplayAvailable()){Button other=iconBtn("Buscar otros TV / proyectores",R.drawable.pv_ic_fullscreen);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(-1,dp(52));op.setMargins(0,dp(8),0,dp(8));tvResults.addView(other,op);other.setOnClickListener(v->{if(tvAnalysisStatus!=null)tvAnalysisStatus.setText("Abriendo búsqueda inalámbrica del teléfono…");openWirelessDisplay();});}}

  void startAutoConnect(TvDevice device){if(device==null)return;if(current==null){toast("Selecciona primero el canal que deseas enviar");return;}final long gen=++autoConnectGeneration;boolean internet=hasValidatedInternet(),local=hasLocalNetwork();int castScore=device.cast==null?0:TvOutputUtil.score("CAST",internet,local,currentDirectFriendly(),true);int dlnaScore=device.dlna==null?0:TvOutputUtil.score("DLNA",internet,local,currentDlnaFriendly(),true);String preferred=getSharedPreferences("tvplus",MODE_PRIVATE).getString(devicePrefKey(device),"");List<String> order=TvConnectPlanner.order(device.cast!=null,castScore,device.dlna!=null,dlnaScore,systemWirelessDisplayAvailable(),preferred);if(order.isEmpty()){toast("No hay método compatible para este dispositivo");return;}updateAutoConnectUi(device,"Iniciando conexión automática…");tryAutoMethod(device,order,0,gen,new ArrayList<>());}
  void tryAutoMethod(TvDevice d,List<String> order,int index,long gen,List<String> failures){if(gen!=autoConnectGeneration||!"cast".equals(page))return;if(index>=order.size()){updateAutoConnectUi(d,"No fue posible conectar automáticamente");toast("No se pudo conectar a "+d.name);return;}String method=order.get(index);String label="CAST".equals(method)?"conexión directa":"DLNA".equals(method)?"conexión de red":"pantalla inalámbrica";updateAutoConnectUi(d,"Probando "+(index+1)+"/"+order.size()+" · "+label+"…");ConnectCallback cb=(ok,detail)->{if(gen!=autoConnectGeneration)return;if(ok){activeTvMethod=method;activeTvTarget="CAST".equals(method)?d.cast:("DLNA".equals(method)?d.dlna:null);if(!"WIRELESS_DISPLAY".equals(method))getSharedPreferences("tvplus",MODE_PRIVATE).edit().putString(devicePrefKey(d),method).apply();updateAutoConnectUi(d,"Conectado · "+detail);updateTvButton();updateNowBar();toast("Conectado a "+d.name);return;}failures.add(detail);tryAutoMethod(d,order,index+1,gen,failures);};if("CAST".equals(method))tryCastAuto(d.cast,gen,cb);else if("DLNA".equals(method))tryDlnaAuto(d.dlna,cb);else{activeTvMethod="";activeTvTarget=null;updateAutoConnectUi(d,"Última opción · activa Pantalla inalámbrica y selecciona "+d.name);toast("Activa Pantalla inalámbrica y selecciona el TV o proyector");openWirelessDisplay();updateTvButton();updateNowBar();}}
  void updateAutoConnectUi(TvDevice d,String message){if(castStatus!=null)castStatus.setText(d==null?message:d.name+" · "+message);if(tvAnalysisStatus!=null)tvAnalysisStatus.setText(message);}

  MediaRouter.RouteInfo findCastRoute(TvTarget target){if(target==null||mediaRouter==null)return null;try{for(MediaRouter.RouteInfo route:mediaRouter.getRoutes()){if(route==null)continue;if(!target.routeId.isEmpty()&&target.routeId.equals(route.getId()))return route;if(target.name.equalsIgnoreCase(String.valueOf(route.getName()))&&route.matchesSelector(castSelector))return route;}}catch(Throwable ignored){}return null;}
  void tryCastAuto(TvTarget target,long gen,ConnectCallback cb){if(target==null||!ensureCastReady()){cb.done(false,"Cast no disponible");return;}MediaRouter.RouteInfo route=findCastRoute(target);if(route==null){cb.done(false,"receptor Cast ya no disponible");return;}try{mediaRouter.selectRoute(route);}catch(Throwable e){cb.done(false,"Cast: "+e.getClass().getSimpleName());return;}waitCastSession(target,gen,0,cb);}
  void waitCastSession(TvTarget target,long gen,int attempt,ConnectCallback cb){if(gen!=autoConnectGeneration)return;CastSession s=currentCastSession();if(s!=null&&castConnected()){String name=castDeviceName(s);if(target==null||name.equalsIgnoreCase(target.name)||attempt>=2){loadCastAuto(s,cb);return;}}if(attempt>=9){cb.done(false,"Cast no estableció sesión");return;}mainHandler.postDelayed(()->waitCastSession(target,gen,attempt+1,cb),650);}
  void loadCastAuto(CastSession s,ConnectCallback cb){try{if(s==null||current==null){cb.done(false,"Cast sin sesión o canal");return;}RemoteMediaClient client=s.getRemoteMediaClient();if(client==null){cb.done(false,"Cast sin cliente multimedia");return;}com.google.android.gms.cast.MediaMetadata md=new com.google.android.gms.cast.MediaMetadata(com.google.android.gms.cast.MediaMetadata.MEDIA_TYPE_GENERIC);md.putString(com.google.android.gms.cast.MediaMetadata.KEY_TITLE,current.name);md.putString(com.google.android.gms.cast.MediaMetadata.KEY_SUBTITLE,cleanGroup(current.group));if(current.logo!=null&&!current.logo.isEmpty())md.addImage(new WebImage(Uri.parse(current.logo)));com.google.android.gms.cast.MediaInfo info=new com.google.android.gms.cast.MediaInfo.Builder(current.url).setStreamType(com.google.android.gms.cast.MediaInfo.STREAM_TYPE_LIVE).setContentType(castContentType(current.url)).setMetadata(md).build();com.google.android.gms.cast.MediaLoadRequestData req=new com.google.android.gms.cast.MediaLoadRequestData.Builder().setMediaInfo(info).setAutoplay(true).build();client.load(req).setResultCallback(result->{boolean ok=result!=null&&result.getStatus()!=null&&result.getStatus().isSuccess();mainHandler.post(()->{if(ok){if(player!=null)player.pause();cb.done(true,"reproducción directa");}else cb.done(false,"Cast rechazó la reproducción");});});}catch(Throwable e){cb.done(false,"Cast: "+e.getClass().getSimpleName());}}

  void discoverDlna(final long gen,boolean internet,boolean local,boolean friendly){tvIo.submit(()->{ArrayList<TvTarget> found=new ArrayList<>();WifiManager.MulticastLock lock=null;DatagramSocket socket=null;try{WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);if(wm!=null){lock=wm.createMulticastLock("PalmaVisionDLNA");lock.setReferenceCounted(false);lock.acquire();}socket=new DatagramSocket();socket.setReuseAddress(true);socket.setSoTimeout(450);String req="M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 2\r\nST: urn:schemas-upnp-org:device:MediaRenderer:1\r\n\r\n";byte[] out=req.getBytes(StandardCharsets.UTF_8);DatagramPacket p=new DatagramPacket(out,out.length,InetAddress.getByName("239.255.255.250"),1900);socket.send(p);long until=SystemClock.elapsedRealtime()+3200;HashSet<String> seen=new HashSet<>();while(SystemClock.elapsedRealtime()<until){try{byte[] buf=new byte[8192];DatagramPacket in=new DatagramPacket(buf,buf.length);socket.receive(in);String raw=new String(in.getData(),0,in.getLength(),StandardCharsets.UTF_8);String loc=TvOutputUtil.header(raw,"LOCATION");if(loc.isEmpty()||!seen.add(loc))continue;TvTarget target=fetchDlnaTarget(loc,internet,local,friendly);if(target!=null)found.add(target);}catch(SocketTimeoutException ignored){}}}catch(Exception ignored){}finally{if(socket!=null)socket.close();try{if(lock!=null&&lock.isHeld())lock.release();}catch(Exception ignored){}}mainHandler.post(()->{if(gen!=tvScanGeneration||!"cast".equals(page))return;synchronized(tvTargets){for(TvTarget t:found){boolean dupe=false;for(TvTarget e:tvTargets)if("DLNA".equals(e.tech)&&e.location.equals(t.location)){dupe=true;break;}if(!dupe)tvTargets.add(t);}}rebuildTvDevices();renderTvDevices(internet,local,found.isEmpty()?"Búsqueda completa · sin DLNA adicional":"Búsqueda completa · "+tvDevices.size()+" dispositivo(s)");});});}
  TvTarget fetchDlnaTarget(String location,boolean internet,boolean local,boolean friendly){HttpURLConnection c=null;try{URL u=new URL(location);c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(1800);c.setReadTimeout(2200);c.setRequestProperty("User-Agent","PalmaVision/2.4.0");String xml=readAll(c.getInputStream());String name=TvOutputUtil.friendlyName(xml);String ctl=TvOutputUtil.avTransportControlUrl(xml);String serviceType=TvOutputUtil.avTransportServiceType(xml);String control=TvOutputUtil.resolveControlUrl(location,ctl);if(name.isEmpty())name=u.getHost();if(control.isEmpty()||serviceType.isEmpty())return null;return new TvTarget("DLNA",name,"Receptor detectado",TvOutputUtil.score("DLNA",internet,local,friendly,true),location,control,serviceType,"",true);}catch(Exception e){return null;}finally{if(c!=null)c.disconnect();}}
  String readAll(InputStream in)throws IOException{try(BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder b=new StringBuilder();String line;while((line=br.readLine())!=null)b.append(line).append('\n');return b.toString();}}
  String dlnaMime(String url){String u=url==null?"":url.toLowerCase(Locale.ROOT);if(u.contains(".mp4"))return "video/mp4";if(u.contains(".m3u8")||u.contains("format=m3u8"))return "application/vnd.apple.mpegurl";return "video/mpeg";}
  String dlnaMetadata(String url,String name){String mime=dlnaMime(url);return "&lt;DIDL-Lite xmlns=\"urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:upnp=\"urn:schemas-upnp-org:metadata-1-0/upnp/\"&gt;&lt;item id=\"0\" parentID=\"0\" restricted=\"1\"&gt;&lt;dc:title&gt;"+TvOutputUtil.xmlEscape(name)+"&lt;/dc:title&gt;&lt;upnp:class&gt;object.item.videoItem&lt;/upnp:class&gt;&lt;res protocolInfo=\"http-get:*:"+mime+":*\"&gt;"+TvOutputUtil.xmlEscape(url)+"&lt;/res&gt;&lt;/item&gt;&lt;/DIDL-Lite&gt;";}
  void sendToDlna(TvTarget target){tryDlnaAuto(target,(ok,detail)->{if(ok)toast("Canal enviado a "+target.name);else toast("DLNA: "+detail);});}
  void tryDlnaAuto(TvTarget target,ConnectCallback cb){if(target==null||current==null){cb.done(false,"DLNA sin dispositivo o canal");return;}final String url=current.url,name=current.name;tvIo.submit(()->{String failure="";try{String meta=dlnaMetadata(url,name);String set="<InstanceID>0</InstanceID><CurrentURI>"+TvOutputUtil.xmlEscape(url)+"</CurrentURI><CurrentURIMetaData>"+meta+"</CurrentURIMetaData>";try{dlnaSoap(target.controlUrl,target.serviceType,"SetAVTransportURI",set);}catch(IOException first){String fallback="<InstanceID>0</InstanceID><CurrentURI>"+TvOutputUtil.xmlEscape(url)+"</CurrentURI><CurrentURIMetaData></CurrentURIMetaData>";dlnaSoap(target.controlUrl,target.serviceType,"SetAVTransportURI",fallback);}dlnaSoap(target.controlUrl,target.serviceType,"Play","<InstanceID>0</InstanceID><Speed>1</Speed>");SystemClock.sleep(650);String info=dlnaSoap(target.controlUrl,target.serviceType,"GetTransportInfo","<InstanceID>0</InstanceID>");String state=TvOutputUtil.transportState(info);if("STOPPED".equalsIgnoreCase(state)||"NO_MEDIA_PRESENT".equalsIgnoreCase(state))throw new IOException("TV no inició la reproducción");}catch(Exception e){failure=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}final String err=failure;mainHandler.post(()->{if(err.isEmpty()){if(player!=null)player.pause();cb.done(true,"reproducción por red");}else cb.done(false,err);});});}
  String dlnaSoap(String control,String serviceType,String action,String inner)throws IOException{String st=(serviceType==null||serviceType.isEmpty())?"urn:schemas-upnp-org:service:AVTransport:1":serviceType;String body="<?xml version=\"1.0\" encoding=\"utf-8\"?><s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\" s:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"><s:Body><u:"+action+" xmlns:u=\""+st+"\">"+inner+"</u:"+action+"></s:Body></s:Envelope>";byte[] data=body.getBytes(StandardCharsets.UTF_8);HttpURLConnection c=(HttpURLConnection)new URL(control).openConnection();try{c.setConnectTimeout(3000);c.setReadTimeout(4500);c.setDoOutput(true);c.setRequestMethod("POST");c.setRequestProperty("Content-Type","text/xml; charset=\"utf-8\"");c.setRequestProperty("SOAPACTION","\""+st+"#"+action+"\"");c.setRequestProperty("Connection","close");c.setFixedLengthStreamingMode(data.length);try(OutputStream os=c.getOutputStream()){os.write(data);}int code=c.getResponseCode();InputStream bodyStream=code>=200&&code<300?c.getInputStream():c.getErrorStream();String response=bodyStream==null?"":readAll(bodyStream);if(code<200||code>=300){String upnp=TvOutputUtil.upnpError(response);throw new IOException(upnp.isEmpty()?"HTTP "+code:"HTTP "+code+" · "+upnp);}return response;}finally{c.disconnect();}}

  interface ConnectCallback{void done(boolean ok,String detail);}


  void ensureDualPlayer(){if(dualPlayer==null){dualPlayer=new ExoPlayer.Builder(this).build();dualPlayer.setVolume(0f);}if(dualPlayerView==null){dualPlayerView=new PlayerView(this);dualPlayerView.setUseController(true);dualPlayerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);dualPlayerView.setBackgroundColor(Color.BLACK);}}
