  void attachMainPlayer(){if(playerView==null){playerView=new PlayerView(this);playerView.setUseController(true);playerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);playerView.setFocusable(true);}applyResizeMode(playerView);ViewParent p=playerView.getParent();if(p instanceof ViewGroup)((ViewGroup)p).removeView(playerView);if(homePlayerHolder!=null){homePlayerHolder.addView(playerView,0,new FrameLayout.LayoutParams(-1,-1));if(player!=null)playerView.setPlayer(player);ensureSubtitleLayer();}}

  void initPlayer(){player=new ExoPlayer.Builder(this).build();applyLanguagePrefs();player.addListener(new Player.Listener(){
    @Override public void onPlaybackStateChanged(int s){
      if(s==Player.STATE_READY){cancelStartupWatchdog();retries=0;long ms=connectStartedAt>0?SystemClock.elapsedRealtime()-connectStartedAt:0;setHealth(current,ms>2500?HEALTH_WARN:HEALTH_OK,ms>2500?"Lento":"Disponible",ms);setLiveStatus("En vivo"+channelPositionText(),CYAN);}
      else if(s==Player.STATE_BUFFERING)setLiveStatus(retries>0?"Reconectando "+retries+"/3…":"Cargando señal…",CYAN);
      else if(s==Player.STATE_ENDED)setLiveStatus("Transmisión finalizada",ORANGE);
    }
    @Override public void onIsPlayingChanged(boolean playing){if(playing&&player.getPlaybackState()==Player.STATE_READY)setLiveStatus("En vivo"+channelPositionText(),CYAN);}
    @Override public void onPlayerError(PlaybackException e){cancelStartupWatchdog();setHealth(current,HEALTH_BAD,"Problema",0);setLiveStatus(errorLabel(e),ORANGE);if(autoRetryEnabled)autoRetry();}
  });attachMainPlayer();ensureSubtitleLayer();}

  String channelPlaybackKey(String kind,Channel ch){return kind+"_"+sha1(ch==null?"none":ch.id);}
  String channelString(String kind,Channel ch,String fallback){if(ch==null)return fallback;return getSharedPreferences("tvplus",MODE_PRIVATE).getString(channelPlaybackKey(kind,ch),fallback);}
  int channelInt(String kind,Channel ch,int fallback){if(ch==null)return fallback;return getSharedPreferences("tvplus",MODE_PRIVATE).getInt(channelPlaybackKey(kind,ch),fallback);}
  boolean hasChannelPlaybackOverride(Channel ch){if(ch==null)return false;SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);return p.contains(channelPlaybackKey("channel_audio",ch))||p.contains(channelPlaybackKey("channel_subtitle",ch))||p.contains(channelPlaybackKey("channel_subtitle_size",ch));}
  String effectiveAudioLang(Channel ch){return channelString("channel_audio",ch,preferredAudioLang);}
  String effectiveSubtitleLang(Channel ch){return channelString("channel_subtitle",ch,preferredSubtitleLang);}
  int effectiveSubtitleSize(Channel ch){return channelInt("channel_subtitle_size",ch,preferredSubtitleSize);}
  String subtitleSizeLabel(int size){switch(size){case 0:return "Pequeño";case 2:return "Grande";case 3:return "Muy grande";default:return "Mediano";}}
  float subtitleSizeSp(int size){switch(size){case 0:return 15f;case 2:return 23f;case 3:return 28f;default:return 19f;}}
  void ensureSubtitleLayer(){ensureSubtitleLayer(playerView,current);}
  void ensureSubtitleLayer(PlayerView view,Channel ch){try{if(view!=null&&view.getSubtitleView()!=null){view.getSubtitleView().setVisibility(View.VISIBLE);view.getSubtitleView().setApplyEmbeddedStyles(true);view.getSubtitleView().setApplyEmbeddedFontSizes(false);view.getSubtitleView().setFixedTextSize(android.util.TypedValue.COMPLEX_UNIT_SP,subtitleSizeSp(effectiveSubtitleSize(ch)));}}catch(Exception ignored){}}
  String langLabel(String code){if(code==null||"auto".equals(code))return "Automático";if("off".equals(code))return "Desactivados";if("es".equals(code))return "Español";if("en".equals(code))return "Inglés";if("pt".equals(code))return "Portugués";if("fr".equals(code))return "Francés";if("de".equals(code))return "Alemán";if("it".equals(code))return "Italiano";return code;}
  void applyLanguagePrefs(){applyLanguagePrefs(player,current);}
  void applyLanguagePrefs(ExoPlayer target,Channel ch){if(target==null)return;String audio=effectiveAudioLang(ch),subs=effectiveSubtitleLang(ch);TrackSelectionParameters.Builder b=target.getTrackSelectionParameters().buildUpon();try{b.clearOverridesOfType(C.TRACK_TYPE_AUDIO);b.clearOverridesOfType(C.TRACK_TYPE_TEXT);}catch(Exception ignored){}b.setPreferredAudioLanguage("auto".equals(audio)?null:audio);if("off".equals(subs)){b.setTrackTypeDisabled(C.TRACK_TYPE_TEXT,true);b.setPreferredTextLanguage(null);}else{b.setTrackTypeDisabled(C.TRACK_TYPE_TEXT,false);b.setPreferredTextLanguage("auto".equals(subs)?null:subs);b.setSelectUndeterminedTextLanguage(true);}target.setTrackSelectionParameters(b.build());if(target==player)ensureSubtitleLayer(playerView,ch);else if(target==dualPlayer)ensureSubtitleLayer(dualPlayerView,ch);}
  void chooseLanguage(boolean audio){chooseGlobalLanguage(audio);}
  void chooseGlobalLanguage(boolean audio){String[] labels=audio?new String[]{"Automático","Español","Inglés","Portugués","Francés","Alemán","Italiano"}:new String[]{"Automático","Desactivados","Español","Inglés","Portugués","Francés","Alemán","Italiano"};String[] codes=audio?new String[]{"auto","es","en","pt","fr","de","it"}:new String[]{"auto","off","es","en","pt","fr","de","it"};AlertDialog d=new AlertDialog.Builder(this).setTitle(audio?"Idioma de audio general":"Idioma de subtítulos general").setItems(labels,(x,w)->{if(audio)preferredAudioLang=codes[w];else preferredSubtitleLang=codes[w];savePrefs();applyLanguagePrefs();showLanguageSettings();}).setNegativeButton("Cancelar",null).create();styleDialog(d);}
  void chooseGlobalSubtitleSize(){String[] labels={"Pequeño","Mediano","Grande","Muy grande"};AlertDialog d=new AlertDialog.Builder(this).setTitle("Tamaño general de subtítulos").setItems(labels,(x,w)->{preferredSubtitleSize=w;savePrefs();ensureSubtitleLayer();showLanguageSettings();}).setNegativeButton("Cancelar",null).create();styleDialog(d);}
  void chooseChannelLanguage(boolean audio){if(current==null){toast("Selecciona un canal primero");return;}String general=audio?preferredAudioLang:preferredSubtitleLang;String[] base=audio?new String[]{"Automático","Español","Inglés","Portugués","Francés","Alemán","Italiano"}:new String[]{"Automático","Desactivados","Español","Inglés","Portugués","Francés","Alemán","Italiano"};String[] codes=audio?new String[]{"auto","es","en","pt","fr","de","it"}:new String[]{"auto","off","es","en","pt","fr","de","it"};String[] labels=new String[base.length+1];labels[0]="Usar configuración general · "+langLabel(general);System.arraycopy(base,0,labels,1,base.length);AlertDialog d=new AlertDialog.Builder(this).setTitle((audio?"Audio":"Subtítulos")+" · "+current.name).setItems(labels,(x,w)->{SharedPreferences.Editor e=getSharedPreferences("tvplus",MODE_PRIVATE).edit();String key=channelPlaybackKey(audio?"channel_audio":"channel_subtitle",current);if(w==0)e.remove(key);else e.putString(key,codes[w-1]);e.apply();applyLanguagePrefs();showMediaLanguageMenu();}).setNegativeButton("Cancelar",null).create();styleDialog(d);}
  void chooseChannelSubtitleSize(){if(current==null){toast("Selecciona un canal primero");return;}String[] labels={"Usar configuración general · "+subtitleSizeLabel(preferredSubtitleSize),"Pequeño","Mediano","Grande","Muy grande"};AlertDialog d=new AlertDialog.Builder(this).setTitle("Tamaño de subtítulos · "+current.name).setItems(labels,(x,w)->{SharedPreferences.Editor e=getSharedPreferences("tvplus",MODE_PRIVATE).edit();String key=channelPlaybackKey("channel_subtitle_size",current);if(w==0)e.remove(key);else e.putInt(key,w-1);e.apply();ensureSubtitleLayer();showMediaLanguageMenu();}).setNegativeButton("Cancelar",null).create();styleDialog(d);}
  void clearChannelPlaybackOverrides(){if(current==null)return;getSharedPreferences("tvplus",MODE_PRIVATE).edit().remove(channelPlaybackKey("channel_audio",current)).remove(channelPlaybackKey("channel_subtitle",current)).remove(channelPlaybackKey("channel_subtitle_size",current)).apply();applyLanguagePrefs();toast("Este canal vuelve a usar la configuración general");}
  void showLanguageSettings(){LinearLayout p=pageBase("Idioma y subtítulos","Preferencias generales de reproducción");Button audio=menuCard("Audio · "+langLabel(preferredAudioLang),"Idioma general cuando no existe ajuste específico del canal",R.drawable.pv_ic_audio),subs=menuCard("Subtítulos · "+langLabel(preferredSubtitleLang),"Idioma general cuando el canal ofrece subtítulos",R.drawable.pv_ic_subtitles),size=menuCard("Tamaño de subtítulos · "+subtitleSizeLabel(preferredSubtitleSize),"Tamaño general del texto en pantalla",R.drawable.pv_ic_subtitles);for(Button b:new Button[]{audio,subs,size}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(68));lp.setMargins(0,dp(7),0,dp(7));p.addView(b,lp);}audio.setOnClickListener(v->chooseGlobalLanguage(true));subs.setOnClickListener(v->chooseGlobalLanguage(false));size.setOnClickListener(v->chooseGlobalSubtitleSize());}
  void showMediaLanguageMenu(){if(current==null){toast("Selecciona un canal primero");return;}String a=langLabel(effectiveAudioLang(current)),s=langLabel(effectiveSubtitleLang(current)),z=subtitleSizeLabel(effectiveSubtitleSize(current));ArrayList<String> opts=new ArrayList<>();opts.add("Audio · "+a);opts.add("Subtítulos · "+s);opts.add("Tamaño de subtítulos · "+z);opts.add("Pistas de audio disponibles");opts.add("Pistas de subtítulos disponibles");if(hasChannelPlaybackOverride(current))opts.add("Restablecer este canal a configuración general");AlertDialog d=new AlertDialog.Builder(this).setTitle("Idioma y subtítulos").setItems(opts.toArray(new String[0]),(x,w)->{if(w==0)chooseChannelLanguage(true);else if(w==1)chooseChannelLanguage(false);else if(w==2)chooseChannelSubtitleSize();else if(w==3)showTracks(C.TRACK_TYPE_AUDIO);else if(w==4)showTracks(C.TRACK_TYPE_TEXT);else clearChannelPlaybackOverrides();}).setNegativeButton("Cerrar",null).create();styleDialog(d);}


  String programText(Channel ch){Program p=currentPrograms.get(ch.id);if(p!=null)return p.title+"  ·  "+hhmm(p.start)+"–"+hhmm(p.stop);if(epgLoading)return "Programa · cargando guía…";if(!epgLastError.isEmpty())return "Programa · error de EPG";return programGuide.containsKey(ch.id)?"Programa · sin emisión actual":"Programa · sin EPG para este canal";}
  String hhmm(long ms){return new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(ms));}
  void bindLogo(ImageView iv,Channel ch){iv.setTag(ch.id);Bitmap b=ch.logo.isEmpty()?null:logoCache.get(ch.logo);if(b!=null){iv.setAlpha(1f);iv.setImageBitmap(b);return;}iv.setAlpha(.38f);iv.setImageResource(R.drawable.pv_logo);if(ch.logo.isEmpty()||!logoLoading.add(ch.logo))return;final String url=ch.logo,id=ch.id;imageIo.submit(()->{Bitmap bmp=null;InputStream in=null;try{URLConnection cn=new URL(url).openConnection();cn.setConnectTimeout(3500);cn.setReadTimeout(4500);cn.setRequestProperty("User-Agent","PalmaVision/2.4.0");in=cn.getInputStream();Bitmap raw=BitmapFactory.decodeStream(in);if(raw!=null){int max=192,w=raw.getWidth(),h=raw.getHeight();if(w>max||h>max){float scale=Math.min((float)max/w,(float)max/h);Bitmap small=Bitmap.createScaledBitmap(raw,Math.max(1,Math.round(w*scale)),Math.max(1,Math.round(h*scale)),true);if(small!=raw)raw.recycle();bmp=small;}else bmp=raw;}}catch(Exception ignored){}finally{try{if(in!=null)in.close();}catch(Exception ignored){}logoLoading.remove(url);}if(bmp!=null){logoCache.put(url,bmp);final Bitmap ready=bmp;mainHandler.post(()->{if(id.equals(iv.getTag())){iv.setAlpha(1f);iv.setImageBitmap(ready);}});}});}
  void setHealth(Channel ch,int state,String text,long latency){if(ch==null)return;channelHealth.put(ch.id,new Health(state,text,latency,System.currentTimeMillis()));if(adapter!=null)adapter.notifyDataSetChanged();}
  int healthColor(Channel ch){Health h=channelHealth.get(ch.id);if(h==null)return MUTED;if(h.state==HEALTH_OK)return GREEN;if(h.state==HEALTH_WARN)return ORANGE;if(h.state==HEALTH_BAD)return PV_ERROR;if(h.state==HEALTH_VERIFIED)return CYAN;return MUTED;}
  String healthText(Channel ch){Health h=channelHealth.get(ch.id);return h==null?"Sin verificar":h.text;}

  final class ChannelRowHolder{LinearLayout row;ImageView logo,lock,fav;TextView name,meta,prog,health;}
