  View channelRow(Channel ch,boolean active,View old){ChannelRowHolder h;if(old instanceof LinearLayout&&old.getTag() instanceof ChannelRowHolder){h=(ChannelRowHolder)old.getTag();}else{h=new ChannelRowHolder();h.row=new LinearLayout(this);h.row.setOrientation(LinearLayout.HORIZONTAL);h.row.setGravity(Gravity.CENTER_VERTICAL);h.row.setPadding(dp(8),dp(5),dp(8),dp(5));h.logo=new ImageView(this);h.logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);h.row.addView(h.logo,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout text=new LinearLayout(this);text.setOrientation(LinearLayout.VERTICAL);text.setPadding(dp(10),0,dp(5),0);h.name=tv("",14,Color.WHITE);h.name.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.name.setSingleLine(true);h.name.setEllipsize(android.text.TextUtils.TruncateAt.END);h.meta=tv("",11,CYAN);h.meta.setSingleLine(true);h.prog=tv("",11,MUTED);h.prog.setSingleLine(true);h.prog.setEllipsize(android.text.TextUtils.TruncateAt.END);text.addView(h.name,new LinearLayout.LayoutParams(-1,dp(23)));text.addView(h.meta,new LinearLayout.LayoutParams(-1,dp(19)));text.addView(h.prog,new LinearLayout.LayoutParams(-1,dp(19)));h.row.addView(text,new LinearLayout.LayoutParams(0,dp(61),1));LinearLayout right=new LinearLayout(this);right.setOrientation(LinearLayout.VERTICAL);right.setGravity(Gravity.CENTER);h.health=tv("",9,MUTED);h.health.setGravity(Gravity.CENTER);h.health.setSingleLine(true);right.addView(h.health,new LinearLayout.LayoutParams(dp(78),dp(22)));LinearLayout marks=new LinearLayout(this);marks.setGravity(Gravity.CENTER);h.lock=new ImageView(this);h.lock.setImageResource(R.drawable.pv_ic_lock);h.lock.setPadding(dp(5),dp(5),dp(5),dp(5));marks.addView(h.lock,new LinearLayout.LayoutParams(dp(30),dp(34)));h.fav=new ImageView(this);h.fav.setImageResource(R.drawable.pv_ic_star);h.fav.setPadding(dp(5),dp(5),dp(5),dp(5));marks.addView(h.fav,new LinearLayout.LayoutParams(dp(30),dp(34)));right.addView(marks,new LinearLayout.LayoutParams(dp(78),dp(36)));h.row.addView(right,new LinearLayout.LayoutParams(dp(82),dp(60)));h.row.setTag(h);}h.row.setBackground(rounded(active?PV_PRIMARY:Color.argb(232,6,29,50),12));h.name.setText(ch.name);h.meta.setText(cleanGroup(ch.group));h.prog.setText(programText(ch));h.health.setText("● "+healthText(ch));h.health.setTextColor(healthColor(ch));h.lock.setAlpha(isBlocked(ch)?1f:.12f);h.fav.setAlpha(favorites.contains(ch.id)?1f:.28f);bindLogo(h.logo,ch);return h.row;}

  final class ChannelAdapter extends BaseAdapter{public int getCount(){return shown.size();}public Channel getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){Channel ch=getItem(p);boolean active=current!=null&&current.id.equals(ch.id);return channelRow(ch,active,old);}}

  void bindList(){adapter=new ChannelAdapter();channelList.setAdapter(adapter);channelList.setOnItemClickListener((p,v,pos,id)->play(shown.get(pos)));channelList.setOnItemLongClickListener((p,v,pos,id)->{showChannelActions(shown.get(pos));return true;});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){if(searchFilterTask!=null)mainHandler.removeCallbacks(searchFilterTask);searchFilterTask=MainActivity.this::filter;mainHandler.postDelayed(searchFilterTask,180);}public void afterTextChanged(android.text.Editable e){}});}


  String cleanGroup(String raw){if(raw==null)return "Otros";String s=raw.trim().replaceFirst("^\\d+\\s+","").replaceFirst("^[^\\p{L}\\p{N}]+","").trim();return s.isEmpty()?"Otros":s;}
  String displayCategory(String cat){return cat!=null&&cat.startsWith("País:")?cat.substring(5):cat;}
  boolean categoryMatch(Channel c,String cat){if(cat==null||cat.equals("Todos"))return true;String raw=c.group==null?"":c.group.trim();String clean=cleanGroup(raw);if(cat.startsWith("País:"))return raw.startsWith("20 ")&&clean.equalsIgnoreCase(cat.substring(5));if(cat.equals("Deportes"))return raw.startsWith("01 ")||clean.equalsIgnoreCase("Deportes");if(cat.equals("Cine en vivo"))return raw.startsWith("02 ")||clean.equalsIgnoreCase("Cine en vivo");if(cat.equals("Series en vivo"))return raw.startsWith("03 ")||clean.equalsIgnoreCase("Series en vivo");if(cat.equals("Religiosos"))return raw.startsWith("04 ")||clean.toLowerCase(Locale.ROOT).contains("cristian");if(cat.equals("Noticias"))return raw.startsWith("05 ")||clean.equalsIgnoreCase("Noticias");if(cat.equals("Infantiles"))return raw.startsWith("06 ")||clean.toLowerCase(Locale.ROOT).contains("infantil");if(cat.equals("Música"))return raw.startsWith("07 ")||clean.equalsIgnoreCase("Música");if(cat.equals("Documentales"))return raw.startsWith("08 ")||clean.toLowerCase(Locale.ROOT).contains("document");if(cat.equals("Entretenimiento"))return raw.startsWith("09 ")||clean.equalsIgnoreCase("Entretenimiento");return clean.equalsIgnoreCase(cat);}
  boolean has(String x,String...keys){for(String k:keys)if(x.contains(k))return true;return false;}

  void filter(){if(adapter==null||search==null)return;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);shown.clear();Set<String> recentSet=new HashSet<>(recents);List<Channel> base=baseForCategory(category);for(Channel c:base){boolean mm=mode.equals("all")||(mode.equals("fav")&&favorites.contains(c.id))||(mode.equals("recent")&&recentSet.contains(c.id));if(mm&&(q.isEmpty()||c.search.contains(q)))shown.add(c);}if(mode.equals("recent")){final Map<String,Integer> rank=new HashMap<>();int i=0;for(String id:recents)rank.put(id,i++);Collections.sort(shown,(a,b)->Integer.compare(rank.containsKey(a.id)?rank.get(a.id):9999,rank.containsKey(b.id)?rank.get(b.id):9999));}adapter.notifyDataSetChanged();count.setText(category.equals("Todos")?shown.size()+" canales":shown.size()+" canales · "+displayCategory(category));}

  void play(Channel c){if(c==null)return;if(isBlocked(c)){requestParentalPin("Canal bloqueado",()->playUnlocked(c));return;}playUnlocked(c);}  void playUnlocked(Channel c){if(c==null)return;pauseRadioForOtherMedia();pauseVodForOtherMedia();if(!networkConnected()){setLiveStatus("Sin conexión de red",ORANGE);return;}if(current!=null&&!current.id.equals(c.id))previous=current;current=c;retries=0;addRecent(c.id);if(title!=null)title.setText(c.name+"  ·  "+cleanGroup(c.group));setLiveStatus("Conectando…",CYAN);if(playerEmpty!=null)playerEmpty.setVisibility(View.GONE);updateFav();startCurrentStream();castCurrentIfConnected();updateNowBar();filter();}
  String currentStreamUrl(){if(current==null)return "";List<String> alts=alternateStreams.get(streamAltKey(current));if(alts==null||alts.isEmpty()||retries<2)return current.url;int idx=Math.min(alts.size()-1,retries-1);return alts.get(idx);}
  void startCurrentStream(){if(current==null)return;playToken++;connectStartedAt=SystemClock.elapsedRealtime();applyLanguagePrefs();String stream=currentStreamUrl();player.setMediaItem(new MediaItem.Builder().setUri(stream).setMediaId(current.id).build());player.prepare();player.play();armStartupWatchdog(playToken);}
  void restart(){if(current==null)return;if(!networkConnected()){setLiveStatus("Sin conexión de red · toca Reconectar",ORANGE);return;}setLiveStatus(retries>0?"Reconectando "+retries+"/3…":"Reconectando…",CYAN);startCurrentStream();}
  void autoRetry(){if(current==null)return;if(retries<3){retries++;setLiveStatus("Reconectando "+retries+"/3…",CYAN);mainHandler.postDelayed(this::restart,700L+retries*700L);}else setLiveStatus("Canal sin respuesta · prueba Verificar",ORANGE);}
  void step(int d){List<Channel> base=!shown.isEmpty()&&current!=null&&shown.contains(current)?shown:all;if(base.isEmpty())return;int i=current==null?-1:base.indexOf(current);if(i<0)i=0;else i=(i+d+base.size())%base.size();play(base.get(i));}
  void toggleFavorite(){toggleFavorite(current);}
  void toggleFavorite(Channel c){if(c==null)return;if(!favorites.add(c.id))favorites.remove(c.id);savePrefs();updateFav();}
  void updateFav(){if(favButton!=null){boolean on=current!=null&&favorites.contains(current.id);favButton.setText(on?"Guardado":"Favorito");favButton.setBackground(buttonBg(on?PV_PRIMARY:PV_BUTTON,on?Color.rgb(20,132,255):PV_BUTTON_FOCUS,14));setButtonIcon(favButton,R.drawable.pv_ic_star,false);}}
  void addRecent(String id){recents.remove(id);recents.addFirst(id);while(recents.size()>30)recents.removeLast();savePrefs();}

  void showMoreMenu(){LinearLayout p=pageBase("Opciones del canal","Funciones adicionales");Button check=menuCard("Verificar canal","Comprueba disponibilidad y tiempo de respuesta",R.drawable.pv_ic_info),lock=menuCard(current!=null&&blockedChannels.contains(current.id)?"Desbloquear canal":"Bloquear canal","Protección con PIN parental",R.drawable.pv_ic_lock),audio=menuCard("Audio e idioma","Selecciona una pista disponible",R.drawable.pv_ic_audio),subs=menuCard("Subtítulos e idioma","Activa, cambia o desactiva subtítulos",R.drawable.pv_ic_subtitles);for(Button b:new Button[]{check,lock,audio,subs}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(68));lp.setMargins(dp(4),dp(6),dp(4),dp(6));p.addView(b,lp);}check.setOnClickListener(v->validateCurrent());lock.setOnClickListener(v->toggleBlockedChannel(current));audio.setOnClickListener(v->showTracks(C.TRACK_TYPE_AUDIO));subs.setOnClickListener(v->showTracks(C.TRACK_TYPE_TEXT));}


  String trackLabel(Format f,int type,int index){String lang=f.language==null?"":f.language;String base=f.label!=null&&!f.label.trim().isEmpty()?f.label.trim():(lang.isEmpty()?(type==C.TRACK_TYPE_AUDIO?"Audio ":"Subtítulo ")+(index+1):langLabel(lang));if(!lang.isEmpty()&&!base.toLowerCase(Locale.ROOT).contains(lang.toLowerCase(Locale.ROOT)))base+=" · "+langLabel(lang);return base;}
  void showTracks(int type){if(current==null){toast("Seleccione un canal primero");return;}Tracks t=player.getCurrentTracks();final List<TrackSelectionOverride> ovs=new ArrayList<>();final List<Format> formats=new ArrayList<>();final List<String> labels=new ArrayList<>();if(type==C.TRACK_TYPE_TEXT)labels.add("Desactivados");for(Tracks.Group g:t.getGroups()){if(g.getType()!=type)continue;for(int i=0;i<g.length;i++){Format f=g.getTrackFormat(i);labels.add(trackLabel(f,type,labels.size()));ovs.add(new TrackSelectionOverride(g.getMediaTrackGroup(),i));formats.add(f);}}if(labels.isEmpty()||(type==C.TRACK_TYPE_TEXT&&labels.size()==1)){toast(type==C.TRACK_TYPE_AUDIO?"Este canal solo ofrece una pista de audio o no informa idiomas":"Este canal no ofrece subtítulos");return;}AlertDialog td=new AlertDialog.Builder(this).setTitle(type==C.TRACK_TYPE_AUDIO?"Pistas de audio":"Pistas de subtítulos").setItems(labels.toArray(new String[0]),(d,w)->{TrackSelectionParameters.Builder b=player.getTrackSelectionParameters().buildUpon();SharedPreferences.Editor e=getSharedPreferences("tvplus",MODE_PRIVATE).edit();if(type==C.TRACK_TYPE_TEXT&&w==0){b.setTrackTypeDisabled(C.TRACK_TYPE_TEXT,true);e.putString(channelPlaybackKey("channel_subtitle",current),"off");}else{int x=type==C.TRACK_TYPE_TEXT?w-1:w;b.setTrackTypeDisabled(type,false);b.setOverrideForType(ovs.get(x));Format f=formats.get(x);if(f.language!=null&&!f.language.trim().isEmpty())e.putString(channelPlaybackKey(type==C.TRACK_TYPE_AUDIO?"channel_audio":"channel_subtitle",current),f.language.trim());}e.apply();player.setTrackSelectionParameters(b.build());ensureSubtitleLayer();toast(type==C.TRACK_TYPE_AUDIO?"Audio cambiado para este canal":"Subtítulos actualizados para este canal");}).setNeutralButton("Idioma y subtítulos",(d,w)->showMediaLanguageMenu()).setNegativeButton("Cerrar",null).create();styleDialog(td);}


  void showSavedPage(String label,boolean fav){clearContent();LinearLayout page=pageBase(label,fav?"Tus canales guardados":"Últimos canales vistos");List<Channel> data=new ArrayList<>();if(fav){for(Channel c:all)if(favorites.contains(c.id))data.add(c);}else{for(String id:recents)for(Channel c:all)if(c.id.equals(id)){data.add(c);break;}}addChannelRows(page,data);}
