  void showChannelActions(Channel ch){if(ch==null)return;String fav=favorites.contains(ch.id)?"Quitar de favoritos":"Agregar a favoritos",lock=blockedChannels.contains(ch.id)?"Desbloquear canal":"Bloquear canal";String[] opts={fav,lock,"Verificar canal"};AlertDialog d=new AlertDialog.Builder(this).setTitle(ch.name).setItems(opts,(x,w)->{if(w==0){toggleFavorite(ch);if(adapter!=null)adapter.notifyDataSetChanged();}else if(w==1)toggleBlockedChannel(ch);else{Channel old=current;current=ch;validateCurrent();current=old;}}).setNegativeButton("Cerrar",null).create();styleDialog(d);}
  boolean isAdultChannel(Channel ch){if(ch==null)return false;String raw=ch.group==null?"":ch.group.trim().toLowerCase(Locale.ROOT);String n=ch.name.toLowerCase(Locale.ROOT);return raw.startsWith("10 ")||raw.contains("18+")||raw.contains("adult")||raw.contains("xxx")||n.contains(" adult ")||n.startsWith("adult ");}
  boolean isBlocked(Channel ch){return parentalEnabled&&ch!=null&&(isAdultChannel(ch)||blockedChannels.contains(ch.id));}
  EditText pinField(String hint){EditText e=sourceField(hint,true);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setTransformationMethod(PasswordTransformationMethod.getInstance());e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(4)});return e;}
  String pinHashV2(String pin,byte[] salt){try{PBEKeySpec spec=new PBEKeySpec(pin.toCharArray(),salt,120000,256);byte[] out=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return Base64.encodeToString(out,Base64.NO_WRAP);}catch(Exception e){return "";}}
  boolean hasParentalPin(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);return !p.getString("parental_pin_hash_v2","").isEmpty()||(parentalPinHash!=null&&!parentalPinHash.isEmpty());}
  void setParentalPin(String pin){byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);String hash=pinHashV2(pin,salt);getSharedPreferences("tvplus",MODE_PRIVATE).edit().putString("parental_pin_hash_v2",hash).putString("parental_pin_salt",Base64.encodeToString(salt,Base64.NO_WRAP)).remove("parental_pin_hash").putInt("pin_failures",0).putLong("pin_locked_until",0L).apply();parentalPinHash="";pinFailures=0;pinLockedUntil=0L;}
  void clearParentalPin(){getSharedPreferences("tvplus",MODE_PRIVATE).edit().remove("parental_pin_hash_v2").remove("parental_pin_salt").remove("parental_pin_hash").putInt("pin_failures",0).putLong("pin_locked_until",0L).apply();parentalPinHash="";pinFailures=0;pinLockedUntil=0L;}
  boolean verifyParentalPin(String pin){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);String h=p.getString("parental_pin_hash_v2",""),s=p.getString("parental_pin_salt","");if(!h.isEmpty()&&!s.isEmpty()){String test=pinHashV2(pin,Base64.decode(s,Base64.NO_WRAP));return MessageDigest.isEqual(h.getBytes(StandardCharsets.UTF_8),test.getBytes(StandardCharsets.UTF_8));}if(parentalPinHash!=null&&!parentalPinHash.isEmpty()&&MessageDigest.isEqual(parentalPinHash.getBytes(StandardCharsets.UTF_8),sha1(pin).getBytes(StandardCharsets.UTF_8))){setParentalPin(pin);return true;}return false;}
  boolean pinLocked(){return System.currentTimeMillis()<pinLockedUntil;}
  void recordPinFailure(){pinFailures++;if(pinFailures>=5){pinLockedUntil=System.currentTimeMillis()+60000L;pinFailures=0;}getSharedPreferences("tvplus",MODE_PRIVATE).edit().putInt("pin_failures",pinFailures).putLong("pin_locked_until",pinLockedUntil).apply();}
  void resetPinFailures(){pinFailures=0;pinLockedUntil=0L;getSharedPreferences("tvplus",MODE_PRIVATE).edit().putInt("pin_failures",0).putLong("pin_locked_until",0L).apply();}
  void createParentalPin(Runnable ok){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(8),dp(16),0);EditText a=pinField("PIN de 4 dígitos"),b=pinField("Confirmar PIN");for(EditText e:new EditText[]{a,b}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(50));p.setMargins(0,dp(5),0,dp(5));box.addView(e,p);}AlertDialog d=new AlertDialog.Builder(this).setTitle("Crear PIN parental").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();styleDialog(d);protectSensitiveDialog(d);Button save=d.getButton(AlertDialog.BUTTON_POSITIVE);if(save!=null)save.setOnClickListener(v->{String p1=a.getText().toString(),p2=b.getText().toString();if(p1.length()!=4||!p1.equals(p2)){toast("El PIN debe tener 4 dígitos y coincidir");return;}setParentalPin(p1);parentalEnabled=true;savePrefs();d.dismiss();toast("Control parental activado");if(ok!=null)ok.run();});}
  void requestParentalPin(String title,Runnable ok){if(!hasParentalPin()){createParentalPin(ok);return;}if(pinLocked()){long sec=Math.max(1,(pinLockedUntil-System.currentTimeMillis()+999)/1000);toast("Demasiados intentos. Intenta de nuevo en "+sec+" segundos");return;}EditText e=pinField("PIN");AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Aceptar",null).create();styleDialog(d);protectSensitiveDialog(d);Button accept=d.getButton(AlertDialog.BUTTON_POSITIVE);if(accept!=null)accept.setOnClickListener(v->{if(verifyParentalPin(e.getText().toString())){resetPinFailures();d.dismiss();if(ok!=null)ok.run();}else{recordPinFailure();e.setText("");if(pinLocked()){d.dismiss();toast("PIN bloqueado durante 60 segundos por seguridad");}else toast("PIN incorrecto · quedan "+(5-pinFailures)+" intentos");}});}

  void toggleBlockedChannel(Channel ch){if(ch==null){toast("Selecciona un canal primero");return;}Runnable work=()->{if(!blockedChannels.add(ch.id)){blockedChannels.remove(ch.id);toast("Canal desbloqueado");}else toast("Canal bloqueado");savePrefs();if(adapter!=null)adapter.notifyDataSetChanged();};if(parentalEnabled)requestParentalPin(blockedChannels.contains(ch.id)?"Desbloquear canal":"Bloquear canal",work);else createParentalPin(work);}
  void showParentalSettings(){LinearLayout p=pageBase("Control parental","Activa la protección y selecciona canales bloqueados");TextView state=tv((parentalEnabled?"Activo":"Desactivado")+" · "+blockedChannels.size()+" canales bloqueados · contenido 18+ protegido cuando está activo",12,parentalEnabled?GREEN:MUTED);state.setPadding(dp(10),dp(6),dp(10),dp(6));p.addView(state,new LinearLayout.LayoutParams(-1,dp(56)));Button toggle=menuCard(parentalEnabled?"Desactivar control parental":"Activar control parental",parentalEnabled?"Requiere PIN":"Crea un PIN de 4 dígitos",parentalEnabled?R.drawable.pv_ic_unlock:R.drawable.pv_ic_lock),manage=primaryIconBtn("Seleccionar canales a bloquear",R.drawable.pv_ic_lock),change=menuCard("Cambiar PIN","Actualiza el PIN parental",R.drawable.pv_ic_settings);LinearLayout.LayoutParams t1=new LinearLayout.LayoutParams(-1,dp(66));t1.setMargins(0,dp(6),0,dp(6));p.addView(toggle,t1);LinearLayout.LayoutParams t2=new LinearLayout.LayoutParams(-1,dp(58));t2.setMargins(0,dp(8),0,dp(8));p.addView(manage,t2);LinearLayout.LayoutParams t3=new LinearLayout.LayoutParams(-1,dp(66));t3.setMargins(0,dp(6),0,dp(6));p.addView(change,t3);toggle.setOnClickListener(v->{if(parentalEnabled)requestParentalPin("Desactivar control parental",()->{parentalEnabled=false;savePrefs();showParentalSettings();});else createParentalPin(this::showParentalChannelManager);});manage.setOnClickListener(v->{if(!hasParentalPin())createParentalPin(this::showParentalChannelManager);else requestParentalPin("Administrar canales",this::showParentalChannelManager);});change.setOnClickListener(v->{if(!hasParentalPin())createParentalPin(this::showParentalSettings);else requestParentalPin("Confirmar PIN actual",()->{clearParentalPin();savePrefs();createParentalPin(this::showParentalSettings);});});}

  void showParentalChannelManager(){LinearLayout p=pageBase("Seleccionar canales","Toca uno o varios canales y luego guarda los bloqueos");HashSet<String> work=new HashSet<>(blockedChannels);TextView selected=tv(work.size()+" seleccionados",12,CYAN);selected.setPadding(dp(8),0,dp(8),0);p.addView(selected,new LinearLayout.LayoutParams(-1,dp(28)));EditText q=sourceField("Buscar canal o categoría…",false);p.addView(q,new LinearLayout.LayoutParams(-1,dp(48)));ArrayList<Channel> data=new ArrayList<>(all);ListView lv=new ListView(this);BaseAdapter a=new BaseAdapter(){public int getCount(){return data.size();}public Channel getItem(int i){return data.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){Channel ch=getItem(i);LinearLayout row=new LinearLayout(MainActivity.this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(4),dp(8),dp(4));row.setBackground(rounded(Color.argb(232,6,29,50),12));CheckBox cb=new CheckBox(MainActivity.this);cb.setChecked(work.contains(ch.id));cb.setClickable(false);row.addView(cb,new LinearLayout.LayoutParams(dp(44),dp(48)));LinearLayout box=new LinearLayout(MainActivity.this);box.setOrientation(LinearLayout.VERTICAL);TextView n=tv(ch.name,13,Color.WHITE);n.setTypeface(Typeface.DEFAULT,Typeface.BOLD);n.setSingleLine(true);n.setEllipsize(android.text.TextUtils.TruncateAt.END);TextView g=tv(cleanGroup(ch.group),11,MUTED);box.addView(n,new LinearLayout.LayoutParams(-1,dp(24)));box.addView(g,new LinearLayout.LayoutParams(-1,dp(20)));row.addView(box,new LinearLayout.LayoutParams(0,dp(48),1));if(isAdultChannel(ch)){TextView adult=tv("18+",11,ORANGE);adult.setGravity(Gravity.CENTER);row.addView(adult,new LinearLayout.LayoutParams(dp(42),dp(40)));}return row;}};lv.setAdapter(a);lv.setDivider(new ColorDrawable(Color.TRANSPARENT));lv.setDividerHeight(dp(4));p.addView(lv,new LinearLayout.LayoutParams(-1,0,1));q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a1,int b,int d){}public void onTextChanged(CharSequence s,int a1,int b,int d){String x=s.toString().trim().toLowerCase(Locale.ROOT);data.clear();for(Channel ch:all)if(x.isEmpty()||ch.search.contains(x))data.add(ch);a.notifyDataSetChanged();}public void afterTextChanged(android.text.Editable e){}});lv.setOnItemClickListener((x,v,pos,id)->{Channel ch=data.get(pos);if(!work.add(ch.id))work.remove(ch.id);selected.setText(work.size()+" seleccionados");a.notifyDataSetChanged();});LinearLayout batch=new LinearLayout(this);batch.setGravity(Gravity.CENTER);Button mark=iconBtn("Marcar visibles",R.drawable.pv_ic_lock),unmark=iconBtn("Desmarcar visibles",R.drawable.pv_ic_unlock);batch.addView(mark,weight());batch.addView(unmark,weight());p.addView(batch,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);Button cancel=iconBtn("Cancelar",R.drawable.pv_ic_back),save=primaryIconBtn("Guardar bloqueos",R.drawable.pv_ic_lock);actions.addView(cancel,weight());actions.addView(save,weight());p.addView(actions,new LinearLayout.LayoutParams(-1,dp(58)));mark.setOnClickListener(v->{for(Channel ch:data)work.add(ch.id);selected.setText(work.size()+" seleccionados");a.notifyDataSetChanged();});unmark.setOnClickListener(v->{for(Channel ch:data)work.remove(ch.id);selected.setText(work.size()+" seleccionados");a.notifyDataSetChanged();});cancel.setOnClickListener(v->showParentalSettings());save.setOnClickListener(v->{blockedChannels.clear();blockedChannels.addAll(work);parentalEnabled=true;savePrefs();toast(blockedChannels.size()+" canales bloqueados");showParentalSettings();});}


  void showBlockedChannels(){LinearLayout p=pageBase("Canales bloqueados","Toca un canal para desbloquearlo");ArrayList<Channel> data=new ArrayList<>();for(Channel ch:all)if(blockedChannels.contains(ch.id))data.add(ch);if(data.isEmpty()){TextView e=tv("No hay canales bloqueados manualmente.\n\nLos canales 18+ se protegen automáticamente cuando el control parental está activo.",14,MUTED);e.setGravity(Gravity.CENTER);p.addView(e,new LinearLayout.LayoutParams(-1,0,1));return;}ListView lv=new ListView(this);BaseAdapter a=new BaseAdapter(){public int getCount(){return data.size();}public Channel getItem(int i){return data.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){return channelRow(getItem(i),false,old);}};lv.setAdapter(a);lv.setDivider(new ColorDrawable(Color.TRANSPARENT));lv.setDividerHeight(dp(5));p.addView(lv,new LinearLayout.LayoutParams(-1,0,1));lv.setOnItemClickListener((x,v,pos,id)->{Channel ch=data.get(pos);blockedChannels.remove(ch.id);savePrefs();toast("Canal desbloqueado");showBlockedChannels();});}

