  SecretKey xtreamSecretKey()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);String alias="PalmaVision.Xtream.AES";if(ks.containsAlias(alias)){KeyStore.SecretKeyEntry e=(KeyStore.SecretKeyEntry)ks.getEntry(alias,null);return e.getSecretKey();}KeyGenerator kg=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());return kg.generateKey();}
  void securePutXtreamPassword(String value){if(value==null||value.isEmpty())return;try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,xtreamSecretKey());byte[] ct=cipher.doFinal(value.getBytes(StandardCharsets.UTF_8));getSharedPreferences("tvplus",MODE_PRIVATE).edit().putString("xtream_pass_ct",Base64.encodeToString(ct,Base64.NO_WRAP)).putString("xtream_pass_iv",Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)).remove("xtream_pass").apply();}catch(Exception e){toast("No se pudo proteger la contraseña en este dispositivo");}}
  String secureGetXtreamPassword(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);String ct=p.getString("xtream_pass_ct",""),iv=p.getString("xtream_pass_iv","");if(!ct.isEmpty()&&!iv.isEmpty()){try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,xtreamSecretKey(),new GCMParameterSpec(128,Base64.decode(iv,Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(ct,Base64.NO_WRAP)),StandardCharsets.UTF_8);}catch(Exception ignored){return "";}}String legacy=p.getString("xtream_pass","");if(!legacy.isEmpty()){securePutXtreamPassword(legacy);return legacy;}return "";}
  boolean hasStoredXtreamPassword(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);return !p.getString("xtream_pass_ct","").isEmpty()||!p.getString("xtream_pass","").isEmpty();}
  String redactSecrets(String raw){return SecuritySanitizer.redact(raw);}
  void protectSensitiveDialog(AlertDialog d){try{Window w=d.getWindow();if(w!=null)w.addFlags(WindowManager.LayoutParams.FLAG_SECURE);}catch(Exception ignored){}}
  EditText sourceField(String hint,boolean password){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setTextColor(Color.WHITE);e.setHintTextColor(MUTED);e.setTextSize(14);e.setPadding(dp(12),0,dp(12),0);e.setBackground(rounded(PV_SURFACE_2,12));if(password){e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);e.setTransformationMethod(PasswordTransformationMethod.getInstance());e.setLongClickable(false);e.setTextIsSelectable(false);if(Build.VERSION.SDK_INT>=26)e.setAutofillHints(View.AUTOFILL_HINT_PASSWORD);}return e;}
