  void pickM3u(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,OPEN_M3U);}
  @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==OPEN_M3U&&res==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}SharedPreferences.Editor e=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(e).putString("source_type","local").putString("m3u_uri",u.toString()).apply();clearEpg();loadFromUri(u,"Archivo M3U local");showLiveCategories();}}
  void askUrl(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(16),dp(8),dp(16),0);EditText m3u=sourceField("URL M3U · https://servidor/lista.m3u",false),epg=sourceField("EPG XMLTV opcional · https://servidor/epg.xml",false);m3u.setText(p.getString("m3u_url",""));epg.setText(p.getString("epg_url",""));for(EditText f:new EditText[]{m3u,epg}){LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(50));fp.setMargins(0,dp(6),0,0);form.addView(f,fp);}AlertDialog d=new AlertDialog.Builder(this).setTitle("URL M3U").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Cargar",(x,w)->{String u=m3u.getText().toString().trim(),eurl=epg.getText().toString().trim();if(u.startsWith("http://")||u.startsWith("https://")){SharedPreferences.Editor ed=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(ed).putString("source_type","url").putString("m3u_url",u).putString("epg_url",eurl).apply();clearEpg();if(!eurl.isEmpty())queueEpg(eurl,"XMLTV");loadFromUrl(u,"URL M3U");showLiveCategories();}else toast("Ingrese una URL válida");}).create();styleDialog(d);}
  void askXtream(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(16),dp(8),dp(16),0);EditText name=sourceField("Nombre de la lista · Casa, IPTV, Proveedor…",false),server=sourceField("URL del servidor · http(s)://host:puerto",false),user=sourceField("Usuario",false),pass=sourceField(hasStoredXtreamPassword()?"Contraseña guardada · escribe solo para cambiar":"Contraseña",true);name.setText(p.getString("xtream_name",""));server.setText(p.getString("xtream_server",""));user.setText(p.getString("xtream_user",""));for(EditText f:new EditText[]{name,server,user,pass}){LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(50));fp.setMargins(0,dp(6),0,dp(4));form.addView(f,fp);}TextView privacy=tv("La contraseña nunca se vuelve a mostrar y se guarda cifrada en este dispositivo.",11,MUTED);privacy.setPadding(dp(3),dp(6),dp(3),0);form.addView(privacy,new LinearLayout.LayoutParams(-1,dp(42)));AlertDialog d=new AlertDialog.Builder(this).setTitle("Servidor IPTV / Xtream").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Conectar",(x,w)->{String n=name.getText().toString().trim(),s=server.getText().toString().trim(),u=user.getText().toString().trim(),typed=pass.getText().toString(),pw=typed.isEmpty()?secureGetXtreamPassword():typed;if(n.isEmpty())n="Mi IPTV";if(!(s.startsWith("http://")||s.startsWith("https://"))||u.isEmpty()||pw.isEmpty()){toast("Completa URL, usuario y contraseña");return;}final String fn=n,fs=s,fu=u,fpw=pw;Runnable connect=()->{SharedPreferences.Editor ed=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(ed).putString("source_type","xtream").putString("xtream_name",fn).putString("xtream_server",fs).putString("xtream_user",fu).apply();securePutXtreamPassword(fpw);clearEpg();loadXtream(fs,fu,fpw,fn);showLiveCategories();};if(fs.startsWith("http://")){AlertDialog warn=new AlertDialog.Builder(this).setTitle("Conexión no cifrada").setMessage("Este servidor utiliza HTTP. El usuario y la contraseña podrían viajar sin cifrado por la red. Usa HTTPS cuando el proveedor lo permita.").setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(a,b)->connect.run()).create();styleDialog(warn);}else connect.run();}).create();styleDialog(d);protectSensitiveDialog(d);}

  String xtreamM3uUrl(String server,String user,String pass){try{String s=server.endsWith("/")?server.substring(0,server.length()-1):server;return s+"/get.php?username="+URLEncoder.encode(user,"UTF-8")+"&password="+URLEncoder.encode(pass,"UTF-8")+"&type=m3u_plus&output=ts";}catch(Exception e){return "";}}
  String xtreamEpgUrl(String server,String user,String pass){try{String s=server.endsWith("/")?server.substring(0,server.length()-1):server;return s+"/xmltv.php?username="+URLEncoder.encode(user,"UTF-8")+"&password="+URLEncoder.encode(pass,"UTF-8");}catch(Exception e){return "";}}
  void loadXtream(String server,String user,String pass,String name){String u=xtreamM3uUrl(server,user,pass),e=xtreamEpgUrl(server,user,pass);if(u.isEmpty()){toast("No se pudo construir la URL del servidor");return;}clearEpg();if(!e.isEmpty())queueEpg(e,"EPG Xtream");loadFromUrlSafe(u,name==null||name.trim().isEmpty()?"Mi IPTV":name.trim(),"xtream|"+server+"|"+user,true);}
  void queueEpg(String url,String label){pendingEpgUrl=url==null?"":url.trim();pendingEpgLabel=label==null?"EPG":label;}
  void loadQueuedEpgForCurrentList(){if(pendingEpgUrl.isEmpty()||all.isEmpty())return;String u=pendingEpgUrl,l=pendingEpgLabel;pendingEpgUrl="";pendingEpgLabel="";loadXmltv(u,l);}
  void askEpg(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);final EditText e=sourceField("https://servidor/epg.xml",false);e.setText(p.getString("epg_url",""));AlertDialog d=new AlertDialog.Builder(this).setTitle("Guía EPG / XMLTV").setView(e).setNegativeButton("Cancelar",null).setNeutralButton("Quitar guía",(x,w)->{getSharedPreferences("tvplus",MODE_PRIVATE).edit().remove("epg_url").apply();clearEpg();}).setPositiveButton("Cargar",(x,w)->{String u=e.getText().toString().trim();if(u.startsWith("http://")||u.startsWith("https://")){getSharedPreferences("tvplus",MODE_PRIVATE).edit().putString("epg_url",u).apply();queueEpg(u,"XMLTV");loadQueuedEpgForCurrentList();}else toast("Ingrese una URL XMLTV válida");}).create();styleDialog(d);}
  void clearEpg(){++epgGeneration;currentPrograms.clear();programGuide.clear();lastEpgUrl="";activeEpgLabel="Sin EPG";epgLastError="";epgLoading=false;if(adapter!=null)adapter.notifyDataSetChanged();}
  String normalizeEpgKey(String raw){if(raw==null)return "";String x=java.text.Normalizer.normalize(raw,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT);x=x.replaceAll("\\((?:1080p|720p|576p|480p|4k|uhd|fhd|hd)\\)"," ");x=x.replaceAll("\\b(?:1080p|720p|576p|480p|4k|uhd|fhd|hd)\\b"," ");return x.replaceAll("[^a-z0-9]+","").trim();}
  void addEpgAlias(Map<String,String> aliases,String raw,String channelId){String k=normalizeEpgKey(raw);if(k.length()>=3&&!aliases.containsKey(k))aliases.put(k,channelId);}
  String resolveEpgChannel(String xmlId,Map<String,String> exact,Map<String,String> aliases,Map<String,String> xmlAliases){if(xmlId==null)return null;String x=exact.get(xmlId);if(x!=null)return x;x=xmlAliases.get(xmlId);if(x!=null)return x;return aliases.get(normalizeEpgKey(xmlId));}
  long parseXmltvTime(String raw){try{Matcher m=Pattern.compile("^(\\d{14})(?:\\s*([+-]\\d{4}))?").matcher(raw==null?"":raw.trim());if(!m.find())return 0L;String zone=m.group(2);SimpleDateFormat f=new SimpleDateFormat(zone==null?"yyyyMMddHHmmss":"yyyyMMddHHmmss Z",Locale.US);f.setLenient(false);return f.parse(m.group(1)+(zone==null?"":" "+zone)).getTime();}catch(Exception e){return 0L;}}
  InputStream xmltvStream(URLConnection cn,String url)throws IOException{InputStream in=cn.getInputStream();String enc=cn.getContentEncoding();if((enc!=null&&enc.toLowerCase(Locale.ROOT).contains("gzip"))||url.toLowerCase(Locale.ROOT).endsWith(".gz"))return new GZIPInputStream(in);return in;}
  boolean useEpgAutoFallback(String raw){return EpgPolicy.usesAutoFallback(raw);}
  List<String> epgCandidates(String raw){return EpgPolicy.candidates(raw);}
  void mergeScheduleMaps(Map<String,List<Program>> into,Map<String,List<Program>> from){for(Map.Entry<String,List<Program>> e:from.entrySet()){List<Program> dst=into.get(e.getKey());if(dst==null){dst=new ArrayList<>();into.put(e.getKey(),dst);}for(Program p:e.getValue())if(dst.size()<256){boolean dup=false;for(Program q:dst)if(q.start==p.start&&q.stop==p.stop&&q.title.equals(p.title)){dup=true;break;}if(!dup)dst.add(p);}}}
  void loadXmltv(String url,String label){
    final long generation=++epgGeneration;
    final List<Channel> channelSnapshot=new ArrayList<>(all);
    final boolean fallbackMode=useEpgAutoFallback(url);
    lastEpgUrl=url;activeEpgLabel="Cargando EPG…";epgLastError="";epgLoading=true;
    epgIo.submit(()->{
      restoreEpgCache(url,label,generation,channelSnapshot.size());
      ConcurrentHashMap<String,Program> fresh=new ConcurrentHashMap<>();
      ConcurrentHashMap<String,List<Program>> schedules=new ConcurrentHashMap<>();
      Exception last=null;int successSources=0,matchedSources=0;
      try{
        HashMap<String,String> exact=new HashMap<>(),aliases=new HashMap<>();
        for(Channel item:channelSnapshot){exact.put(item.id,item.id);addEpgAlias(aliases,item.id,item.id);addEpgAlias(aliases,item.id.replaceFirst("\\.[A-Za-z]{2,3}$",""),item.id);addEpgAlias(aliases,item.name,item.id);}
        for(String candidate:epgCandidates(url)){
          InputStream in=null;
          try{
            ConcurrentHashMap<String,Program> oneFresh=new ConcurrentHashMap<>();
            ConcurrentHashMap<String,List<Program>> oneSchedules=new ConcurrentHashMap<>();
            HashMap<String,String> xmlAliases=new HashMap<>();
            URLConnection cn=new URL(candidate).openConnection();cn.setConnectTimeout(10000);cn.setReadTimeout(45000);cn.setRequestProperty("User-Agent","PalmaVision/2.4.0");cn.setRequestProperty("Accept","application/xml,text/xml,application/gzip,*/*");
            if(cn instanceof HttpURLConnection){HttpURLConnection h=(HttpURLConnection)cn;h.setInstanceFollowRedirects(true);int code=h.getResponseCode();if(code<200||code>=400)throw new FileNotFoundException("HTTP "+code+" · "+redactSecrets(candidate));}
            in=xmltvStream(cn,candidate);XmlPullParser x=Xml.newPullParser();x.setInput(in,"UTF-8");
            long now=System.currentTimeMillis(),from=now-2L*24L*60L*60L*1000L,limit=now+5L*24L*60L*60L*1000L;
            String programmeChannel=null,startTime=null,stopTime=null,ptitle="",xmlChannelId=null,xmlDisplayName="";
            for(int ev=x.getEventType();ev!=XmlPullParser.END_DOCUMENT;ev=x.next()){
              if(ev==XmlPullParser.START_TAG&&"channel".equals(x.getName())){xmlChannelId=x.getAttributeValue(null,"id");xmlDisplayName="";}
              else if(ev==XmlPullParser.START_TAG&&"display-name".equals(x.getName())&&xmlChannelId!=null){String tx=x.nextText();if(xmlDisplayName.isEmpty())xmlDisplayName=tx;}
              else if(ev==XmlPullParser.END_TAG&&"channel".equals(x.getName())&&xmlChannelId!=null){String app=exact.get(xmlChannelId);if(app==null)app=aliases.get(normalizeEpgKey(xmlChannelId));if(app==null&&!xmlDisplayName.isEmpty())app=aliases.get(normalizeEpgKey(xmlDisplayName));if(app!=null)xmlAliases.put(xmlChannelId,app);xmlChannelId=null;xmlDisplayName="";}
              else if(ev==XmlPullParser.START_TAG&&"programme".equals(x.getName())){String raw=x.getAttributeValue(null,"channel");programmeChannel=resolveEpgChannel(raw,exact,aliases,xmlAliases);startTime=x.getAttributeValue(null,"start");stopTime=x.getAttributeValue(null,"stop");ptitle="";}
              else if(ev==XmlPullParser.START_TAG&&"title".equals(x.getName())&&programmeChannel!=null){ptitle=x.nextText();}
              else if(ev==XmlPullParser.END_TAG&&"programme".equals(x.getName())){if(programmeChannel!=null){long st=parseXmltvTime(startTime),en=parseXmltvTime(stopTime);if(st>0&&en>0){Program pr=new Program(ptitle.isEmpty()?"Programa":ptitle,st,en);if(now>=st&&now<en)oneFresh.put(programmeChannel,pr);if(en>=from&&st<=limit){List<Program> list=oneSchedules.get(programmeChannel);if(list==null){list=new ArrayList<>();oneSchedules.put(programmeChannel,list);}if(list.size()<256)list.add(pr);}}}programmeChannel=null;}
            }
            successSources++;if(!oneSchedules.isEmpty()){matchedSources++;for(Map.Entry<String,Program> e:oneFresh.entrySet())fresh.putIfAbsent(e.getKey(),e.getValue());mergeScheduleMaps(schedules,oneSchedules);}last=null;if(!fallbackMode)break;
          }catch(Exception ex){last=ex;}finally{try{if(in!=null)in.close();}catch(Exception ignored){}}
        }
        if(successSources==0){if(last!=null)throw last;throw new FileNotFoundException("No se encontró una fuente EPG disponible");}
        if(fallbackMode&&matchedSources==0)throw new FileNotFoundException("Las fuentes alternativas respondieron pero no coincidieron con los canales");
        for(List<Program> list:schedules.values())Collections.sort(list,(a,b)->Long.compare(a.start,b.start));
        saveEpgCache(url,schedules);
        final int matched=schedules.size(),nowCount=fresh.size(),total=channelSnapshot.size(),sources=matchedSources;
        mainHandler.post(()->{if(generation!=epgGeneration)return;currentPrograms.clear();currentPrograms.putAll(fresh);programGuide.clear();programGuide.putAll(schedules);epgLoading=false;epgLastError="";lastEpgUrl=url;activeEpgLabel=(fallbackMode?"EPG Auto · "+sources+" fuente(s)":label)+" · "+matched+"/"+total+" canales · "+nowCount+" ahora";if(adapter!=null)adapter.notifyDataSetChanged();});
      }catch(Exception ex){final String err=redactSecrets(ex.getClass().getSimpleName()+(ex.getMessage()==null?"":" · "+ex.getMessage()));mainHandler.post(()->{if(generation!=epgGeneration)return;epgLoading=false;epgLastError=err;if(programGuide.isEmpty())activeEpgLabel="EPG con error";else activeEpgLabel=activeEpgLabel+" · actualización pendiente";if(adapter!=null)adapter.notifyDataSetChanged();});}
    });
  }

  String nowNextText(Channel ch){List<Program> list=programGuide.get(ch.id);if(list==null||list.isEmpty())return "Sin programación disponible";long now=System.currentTimeMillis();Program nowP=null,next=null;for(Program p:list){if(now>=p.start&&now<p.stop)nowP=p;else if(p.start>now){next=p;break;}}String out=nowP==null?"Ahora · sin datos":"Ahora · "+nowP.title+" · "+hhmm(nowP.start)+"–"+hhmm(nowP.stop);if(next!=null)out+="\nDespués · "+next.title+" · "+hhmm(next.start);return out;}
