  void showGuide(){if(programGuide.isEmpty()){if(epgLoading){pvMessage("Programación","La guía EPG se está descargando y procesando.\n\nPuedes seguir usando PalmaVision y volver a Programación en unos momentos.");return;}if(all.isEmpty()){pvMessage("Programación","La lista de canales todavía se está cargando.");return;}String retryUrl=!lastEpgUrl.isEmpty()?lastEpgUrl:detectedPlaylistEpgUrl;if(!retryUrl.isEmpty()){AlertDialog d=new AlertDialog.Builder(this).setTitle("Programación").setMessage(epgLastError.isEmpty()?"La guía todavía no tiene datos disponibles.":"No se pudo cargar la guía.\n\n"+epgLastError+"\n\nURL: "+redactSecrets(retryUrl)).setNegativeButton("Cerrar",null).setPositiveButton("Reintentar",(x,w)->{loadXmltv(retryUrl,"EPG de la lista");toast("Recargando guía EPG");}).setNeutralButton("Configurar",(x,w)->showLists()).create();styleDialog(d);return;}pvMessage("Programación","Esta lista no incluye una URL EPG/XMLTV.\n\nPuedes agregarla en Configuración → Fuentes de TV → Guía EPG / XMLTV.");return;}setPage("guide","Programación");LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(10),dp(8),dp(10),dp(10));page.setBackground(outlinePanel());contentFrame.addView(page,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("Programación",20,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);page.addView(h,new LinearLayout.LayoutParams(-1,dp(38)));TextView s=tv(displayCategory(category)+" · "+activeEpgLabel,12,CYAN);page.addView(s,new LinearLayout.LayoutParams(-1,dp(30)));Button refreshGuide=iconBtn("Actualizar guía",R.drawable.pv_ic_refresh);LinearLayout.LayoutParams rgp=new LinearLayout.LayoutParams(-1,dp(48));rgp.setMargins(0,dp(3),0,dp(6));page.addView(refreshGuide,rgp);refreshGuide.setOnClickListener(v->{String u=!lastEpgUrl.isEmpty()?lastEpgUrl:detectedPlaylistEpgUrl;if(u.isEmpty()){toast("No hay una URL EPG configurada");return;}loadXmltv(u,"EPG actualizada");toast("Actualizando guía EPG…");});List<Channel> source=baseForCategory(category);ArrayList<Channel> data=new ArrayList<>();for(Channel ch:source)if(programGuide.containsKey(ch.id))data.add(ch);if(current!=null&&programGuide.containsKey(current.id)&&!data.contains(current))data.add(0,current);ListView lv=new ListView(this);BaseAdapter a=new BaseAdapter(){public int getCount(){return data.size();}public Channel getItem(int p){return data.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){return guideChannelRow(getItem(p));}};lv.setAdapter(a);lv.setDivider(new ColorDrawable(Color.TRANSPARENT));lv.setDividerHeight(dp(5));page.addView(lv,new LinearLayout.LayoutParams(-1,0,1));lv.setOnItemClickListener((p,v,pos,id)->showChannelSchedule(data.get(pos)));if(data.isEmpty()){TextView e=tv("La guía cargada no coincide con los canales de esta categoría.",14,MUTED);page.addView(e,new LinearLayout.LayoutParams(-1,dp(60)));}}

