  void validateCurrent(){final Channel ch=current;if(ch==null){toast("Selecciona un canal primero");return;}setLiveStatus("Verificando enlace…",CYAN);io.submit(()->{long t=SystemClock.elapsedRealtime();String result;boolean ok=false;HttpURLConnection h=null;try{URL u=new URL(ch.url);URLConnection raw=u.openConnection();raw.setConnectTimeout(6000);raw.setReadTimeout(6000);raw.setRequestProperty("User-Agent","PalmaVision/2.4.0");if(raw instanceof HttpURLConnection){h=(HttpURLConnection)raw;h.setRequestMethod("GET");h.setRequestProperty("Range","bytes=0-1023");h.setInstanceFollowRedirects(true);int code=h.getResponseCode();ok=code>=200&&code<400;result="HTTP "+code+" · "+(SystemClock.elapsedRealtime()-t)+" ms";}else{raw.connect();ok=true;result=u.getProtocol().toUpperCase(Locale.ROOT)+" · "+(SystemClock.elapsedRealtime()-t)+" ms";}}catch(Exception ex){result="Sin respuesta · "+ex.getClass().getSimpleName();}finally{if(h!=null)h.disconnect();}final boolean good=ok;final String msg=result;final long elapsed=SystemClock.elapsedRealtime()-t;runOnUiThread(()->{lastHealth=msg;if(good)setHealth(ch,elapsed>2500?HEALTH_WARN:HEALTH_OK,elapsed>2500?"Lento":"Disponible",elapsed);else setHealth(ch,HEALTH_BAD,"Sin respuesta",elapsed);setLiveStatus(good?"Canal responde · "+msg:"Sin respuesta · "+msg,good?GREEN:ORANGE);toast(good?"Enlace del canal disponible":"El enlace no respondió a la verificación");});});}

