  void disconnectRemoteAndExit(){
    ++autoConnectGeneration;
    String method=activeTvMethod==null?"":activeTvMethod;
    TvTarget target=activeTvTarget;
    if("CAST".equals(method)||castConnected()){
      try{
        CastSession s=currentCastSession();
        if(s!=null&&s.getRemoteMediaClient()!=null)try{s.getRemoteMediaClient().stop();}catch(Throwable ignored){}
        if(castContext!=null&&castContext.getSessionManager()!=null)castContext.getSessionManager().endCurrentSession(true);
      }catch(Throwable ignored){}
      activeTvMethod="";activeTvTarget=null;
      finishAndRemoveTask();
      return;
    }
    if("DLNA".equals(method)&&target!=null&&!target.controlUrl.isEmpty()){
      activeTvMethod="";activeTvTarget=null;
      tvIo.submit(()->{
        try{dlnaSoap(target.controlUrl,target.serviceType,"Stop","<InstanceID>0</InstanceID>");}catch(Exception ignored){}
        mainHandler.post(this::finishAndRemoveTask);
      });
      mainHandler.postDelayed(()->{if(!isFinishing())finishAndRemoveTask();},1800);
      return;
    }
    if("WIRELESS_DISPLAY".equals(method)){
      activeTvMethod="";activeTvTarget=null;
      try{startActivity(new Intent(android.provider.Settings.ACTION_CAST_SETTINGS));}catch(Exception ignored){}
      finishAndRemoveTask();
      return;
    }
    finishAndRemoveTask();
  }
  void confirmExit(){String extra=("CAST".equals(activeTvMethod)||"DLNA".equals(activeTvMethod)||castConnected())?"\n\nTambién se detendrá la reproducción y se desconectará del TV.":"WIRELESS_DISPLAY".equals(activeTvMethod)?"\n\nSe abrirá el panel de transmisión para cerrar la pantalla inalámbrica.":"";AlertDialog d=new AlertDialog.Builder(this).setTitle("Salir de PalmaVision").setMessage("¿Deseas cerrar la aplicación?"+extra).setNegativeButton("Cancelar",null).setPositiveButton("Salir",(x,w)->disconnectRemoteAndExit()).create();styleDialog(d);}
