  void loadSavedSource(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);String type=p.getString("source_type",""),uri=p.getString("m3u_uri",""),url=p.getString("m3u_url",""),epg=p.getString("epg_url","");if("xtream".equals(type)){String n=p.getString("xtream_name","Mi IPTV"),s=p.getString("xtream_server",""),u=p.getString("xtream_user",""),pw=secureGetXtreamPassword();if(!s.isEmpty()&&!u.isEmpty()&&!pw.isEmpty()){loadXtream(s,u,pw,n);return;}}if("local".equals(type)&&!uri.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUri(Uri.parse(uri),"Archivo M3U local");return;}if("url".equals(type)&&!url.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUrl(url,"URL M3U");return;}if(!uri.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUri(Uri.parse(uri),"Archivo M3U local");return;}if(!url.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUrl(url,"URL M3U");return;}if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadDefault();}
