  @Override public boolean dispatchKeyEvent(KeyEvent e){
    if(e.getAction()==KeyEvent.ACTION_DOWN&&"vodplayer".equals(page)&&vodPlayer!=null){
      if(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT||e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_REWIND){seekVodBy(-CachePolicy.seekDeltaForRepeat(e.getRepeatCount()));return true;}
      if(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT||e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_FAST_FORWARD){seekVodBy(CachePolicy.seekDeltaForRepeat(e.getRepeatCount()));return true;}
      if(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_CENTER||e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE){toggleVodPlay();return true;}
    }
    if(e.getAction()==KeyEvent.ACTION_DOWN){if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_NEXT){step(1);return true;}if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PREVIOUS){step(-1);return true;}}
    return super.dispatchKeyEvent(e);
  }
  @Override public void onBackPressed(){
    if("vodplayer".equals(page)){leaveVodPlayer();}
    else if("moviedetail".equals(page)){showMovies();}
    else if("seriesepisodes".equals(page)){showSeries();}
    else if("movies".equals(page)||"series".equals(page)||"radio".equals(page)){showHome();}
    else if("cast".equals(page)){showLivePlayer(category);}else if("dualpicker".equals(page)){showDualView();}else if("dual".equals(page)){showHome();}else if("schedule".equals(page)){showGuide();}else if("guide".equals(page)){showLivePlayer(category);}else if("live".equals(page)){showLiveCategories();}else if("countries".equals(page)){showLiveCategories();}else if("livecats".equals(page)){showHome();}else if(!"home".equals(page)){showHome();}else confirmExit();
  }
