  // ---------------- v2.4.0: recovery cache, VOD, series and music radio ----------------
  File pvCacheDir(){File f=new File(getFilesDir(),"pv_cache");if(!f.exists())f.mkdirs();return f;}
  String safeCacheKey(String prefix,String raw){return prefix+"_"+sha1(raw==null?"":raw);}
  byte[] readLimited(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("Respuesta demasiado grande");out.write(b,0,n);}return out.toByteArray();}
  byte[] httpBytes(String url,int max)throws IOException{URLConnection c=new URL(url).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","PalmaVision/2.4.0");c.setRequestProperty("Accept","*/*");if(c instanceof HttpURLConnection){HttpURLConnection h=(HttpURLConnection)c;h.setInstanceFollowRedirects(true);int code=h.getResponseCode();if(code<200||code>=400)throw new FileNotFoundException("HTTP "+code);}try(InputStream in=c.getInputStream()){return readLimited(in,max);}}
  byte[] encryptCache(byte[] plain)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,xtreamSecretKey());byte[] iv=cipher.getIV(),ct=cipher.doFinal(plain);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(iv.length);out.write(iv);out.write(ct);return out.toByteArray();}
  byte[] decryptCache(byte[] packed)throws Exception{if(packed==null||packed.length<14)throw new IOException("cache-encrypted");int n=packed[0]&255;if(n<8||n>32||packed.length<=1+n)throw new IOException("cache-iv");byte[] iv=Arrays.copyOfRange(packed,1,1+n),ct=Arrays.copyOfRange(packed,1+n,packed.length);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,xtreamSecretKey(),new GCMParameterSpec(128,iv));return cipher.doFinal(ct);}
  List<Channel> channelsFromBytes(byte[] bytes)throws IOException{return parse(new ByteArrayInputStream(bytes));}
  byte[] cachedBytes(String key,boolean sensitive,int max){try{byte[] b=RotatingCache.read(pvCacheDir(),key,0,max);return sensitive&&b!=null?decryptCache(b):b;}catch(Exception e){return null;}}
  void writeCachedBytes(String key,byte[] bytes,boolean sensitive){try{RotatingCache.write(pvCacheDir(),key,sensitive?encryptCache(bytes):bytes,3);}catch(Exception ignored){}}

  void loadFromUrlSafe(String url,String label,String identity,boolean sensitive){
    final String key=safeCacheKey("playlist",identity);setLoading("Cargando lista…",label);
    io.submit(()->{boolean localApplied=false;int previous=0;byte[] cached=cachedBytes(key,sensitive,24*1024*1024);
      if(cached!=null)try{List<Channel> cp=channelsFromBytes(cached);if(!cp.isEmpty()){previous=cp.size();localApplied=true;applyChannels(cp,label+" · copia local");}}catch(Exception ignored){}
      try{byte[] remote=httpBytes(url,24*1024*1024);List<Channel> candidate=channelsFromBytes(remote);if(!CachePolicy.acceptableCount(previous,candidate.size()))throw new IOException("actualización incompleta ("+candidate.size()+" de "+previous+")");writeCachedBytes(key,remote,sensitive);applyChannels(candidate,label);}
      catch(Exception e){final boolean had=localApplied;final String msg=redactSecrets(e.getMessage());runOnUiThread(()->toast(had?"No se reemplazó la lista válida · se mantiene la copia local":"No se pudo cargar la lista: "+msg));}
    });
  }

  String jsonText(String url,int max)throws IOException{return new String(httpBytes(url,max),StandardCharsets.UTF_8);}
  String readJsonCache(String key,int max){try{byte[] b=RotatingCache.read(pvCacheDir(),key,0,max);return b==null?null:new String(b,StandardCharsets.UTF_8);}catch(Exception e){return null;}}
  void writeJsonCache(String key,String json){try{RotatingCache.write(pvCacheDir(),key,json.getBytes(StandardCharsets.UTF_8),3);}catch(Exception ignored){}}
  JSONArray jsonArrayOrNull(String raw){try{return raw==null?null:new JSONArray(raw);}catch(Exception e){return null;}}
  JSONObject jsonObjectOrNull(String raw){try{return raw==null?null:new JSONObject(raw);}catch(Exception e){return null;}}
  boolean xtreamReady(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);return "xtream".equals(p.getString("source_type",""))&&!p.getString("xtream_server","").isEmpty()&&!p.getString("xtream_user","").isEmpty()&&!secureGetXtreamPassword().isEmpty();}
  String xtreamServer(){String s=getSharedPreferences("tvplus",MODE_PRIVATE).getString("xtream_server","").trim();while(s.endsWith("/"))s=s.substring(0,s.length()-1);return s;}
  String xtreamUser(){return getSharedPreferences("tvplus",MODE_PRIVATE).getString("xtream_user","");}
  String xtreamApiUrl(String action,String extra){try{String s=xtreamServer(),u=xtreamUser(),pw=secureGetXtreamPassword();if(s.isEmpty()||u.isEmpty()||pw.isEmpty())return "";String out=s+"/player_api.php?username="+URLEncoder.encode(u,"UTF-8")+"&password="+URLEncoder.encode(pw,"UTF-8")+"&action="+URLEncoder.encode(action,"UTF-8");if(extra!=null&&!extra.isEmpty())out+="&"+extra;return out;}catch(Exception e){return "";}}
  String xtreamStreamUrl(String kind,String id,String ext){String base=xtreamServer(),u=xtreamUser(),pw=secureGetXtreamPassword();String folder="series".equals(kind)?"series":"movie";String x=(ext==null||ext.trim().isEmpty())?"mp4":ext.replaceAll("[^A-Za-z0-9]","");return base+"/"+folder+"/"+Uri.encode(u)+"/"+Uri.encode(pw)+"/"+Uri.encode(id)+"."+x;}
  String providerCacheIdentity(String suffix){return safeCacheKey("catalog",xtreamServer()+"|"+xtreamUser()+"|"+suffix);}

  void showXtreamNeeded(String section){LinearLayout p=pageBase(section,"Conecta un servidor IPTV / Xtream para acceder a esta biblioteca");TextView t=tv("La TV en vivo sigue funcionando como hasta ahora. Para "+section.toLowerCase(Locale.ROOT)+" PalmaVision usa el catálogo VOD del servidor configurado.",14,Color.WHITE);t.setGravity(Gravity.CENTER);t.setPadding(dp(20),dp(25),dp(20),dp(25));p.addView(t,new LinearLayout.LayoutParams(-1,0,1));Button b=primaryIconBtn("Configurar servidor IPTV / Xtream",R.drawable.pv_ic_settings);p.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));b.setOnClickListener(v->askXtream());}
  void showMovies(){if(!xtreamReady()){showXtreamNeeded("Películas");return;}showVodCatalog(false);}
  void showSeries(){if(!xtreamReady()){showXtreamNeeded("Series");return;}showVodCatalog(true);}

  void loadVodCatalog(boolean series){
    final String kind=series?"series":"vod", streamsKey=providerCacheIdentity(kind+"_streams"),catsKey=providerCacheIdentity(kind+"_categories");
    final String catUrl=xtreamApiUrl(series?"get_series_categories":"get_vod_categories",""),streamUrl=xtreamApiUrl(series?"get_series":"get_vod_streams","");
    catalogIo.submit(()->{JSONArray cachedStreams=jsonArrayOrNull(readJsonCache(streamsKey,32*1024*1024)),cachedCats=jsonArrayOrNull(readJsonCache(catsKey,4*1024*1024));int old=cachedStreams==null?0:cachedStreams.length();if(old>0){CatalogPayload cp=parseVodCatalog(cachedStreams,cachedCats,series);mainHandler.post(()->applyVodCatalog(cp,series,true));}
      try{String catsRaw=jsonText(catUrl,4*1024*1024),streamsRaw=jsonText(streamUrl,32*1024*1024);JSONArray cats=new JSONArray(catsRaw),streams=new JSONArray(streamsRaw);if(!CachePolicy.acceptableCount(old,streams.length()))throw new IOException("catálogo remoto incompleto");CatalogPayload cp=parseVodCatalog(streams,cats,series);if(cp.items.isEmpty())throw new IOException("catálogo vacío");writeJsonCache(catsKey,catsRaw);writeJsonCache(streamsKey,streamsRaw);mainHandler.post(()->applyVodCatalog(cp,series,false));}
      catch(Exception ex){if(old==0)mainHandler.post(()->toast("No se pudo cargar "+(series?"series":"películas")+" · "+redactSecrets(ex.getMessage())));}
    });
  }

  CatalogPayload parseVodCatalog(JSONArray streams,JSONArray cats,boolean series){CatalogPayload out=new CatalogPayload();if(cats!=null)for(int i=0;i<cats.length();i++){JSONObject c=cats.optJSONObject(i);if(c==null)continue;String id=c.optString("category_id",""),name=c.optString("category_name","").trim();if(!id.isEmpty()&&!name.isEmpty())out.categories.put(id,name);}for(int i=0;i<streams.length();i++){JSONObject o=streams.optJSONObject(i);if(o==null)continue;String id=series?o.optString("series_id",""):o.optString("stream_id","");String name=o.optString("name","").trim();if(id.isEmpty()||name.isEmpty())continue;String poster=series?o.optString("cover",""):o.optString("stream_icon","");String cat=o.optString("category_id","");String ext=series?"":o.optString("container_extension","mp4");String added=o.optString("last_modified",o.optString("added","0"));String rating=o.optString("rating_5based",o.optString("rating",""));String year=o.optString("year",o.optString("releaseDate",""));out.items.add(new VodItem(id,name,cat,poster,ext,added,rating,year,series));}return out;}
  void applyVodCatalog(CatalogPayload cp,boolean series,boolean cached){ArrayList<VodItem> dest=series?seriesItems:vodItems;LinkedHashMap<String,String> cats=series?seriesCategories:vodCategories;dest.clear();dest.addAll(cp.items);cats.clear();cats.putAll(cp.categories);filterVod(series);if((series&&"series".equals(page))||(!series&&"movies".equals(page)))refreshVodPage(series,cached?"Copia local · actualizando…":"Actualizado · "+dest.size()+" títulos");}

