  void refreshVodPage(boolean series,String label){if(!(series?"series":"movies").equals(page))return;View v=findTagged(contentFrame,"vod_state");if(v instanceof TextView)((TextView)v).setText(label);View grid=findFirst(contentFrame,GridView.class);if(grid instanceof GridView&&((GridView)grid).getAdapter() instanceof BaseAdapter){filterVod(series);((BaseAdapter)((GridView)grid).getAdapter()).notifyDataSetChanged();}}
  View findTagged(ViewGroup root,Object tag){for(int i=0;i<root.getChildCount();i++){View v=root.getChildAt(i);if(tag.equals(v.getTag()))return v;if(v instanceof ViewGroup){View x=findTagged((ViewGroup)v,tag);if(x!=null)return x;}}return null;}
