  void filterVod(boolean series){ArrayList<VodItem> src=series?seriesItems:vodItems,dst=series?seriesShown:vodShown;String cat=series?seriesCategory:vodCategory,q=(series?seriesQuery:vodQuery).trim().toLowerCase(Locale.ROOT),sort=series?seriesSort:vodSort;Set<String> fav=series?seriesFavorites:vodFavorites;dst.clear();String catId="";LinkedHashMap<String,String> map=series?seriesCategories:vodCategories;for(Map.Entry<String,String> e:map.entrySet())if(e.getValue().equals(cat)){catId=e.getKey();break;}for(VodItem x:src){boolean ok="Todas".equals(cat)||("Favoritos".equals(cat)&&fav.contains(x.id))||("Continuar viendo".equals(cat)&&(series?hasSeriesResume(x.id):hasMediaResume("movie",x.id)))||(!catId.isEmpty()&&catId.equals(x.categoryId));if(ok&&(q.isEmpty()||x.search.contains(q)))dst.add(x);}if("A-Z".equals(sort))Collections.sort(dst,(a,b)->a.name.compareToIgnoreCase(b.name));else if("Z-A".equals(sort))Collections.sort(dst,(a,b)->b.name.compareToIgnoreCase(a.name));else if("Año".equals(sort))Collections.sort(dst,(a,b)->b.year.compareTo(a.year));else Collections.sort(dst,(a,b)->compareNumericString(b.added,a.added));}
  int compareNumericString(String a,String b){try{return Long.compare(Long.parseLong(a),Long.parseLong(b));}catch(Exception e){return a.compareTo(b);}}
  int countVodCategory(boolean series,String name){ArrayList<VodItem> src=series?seriesItems:vodItems;if("Todas".equals(name))return src.size();if("Favoritos".equals(name)){Set<String> f=series?seriesFavorites:vodFavorites;int n=0;for(VodItem x:src)if(f.contains(x.id))n++;return n;}if("Continuar viendo".equals(name)){int n=0;for(VodItem x:src)if(series?hasSeriesResume(x.id):hasMediaResume("movie",x.id))n++;return n;}LinkedHashMap<String,String> map=series?seriesCategories:vodCategories;String id="";for(Map.Entry<String,String> e:map.entrySet())if(e.getValue().equals(name)){id=e.getKey();break;}int n=0;for(VodItem x:src)if(id.equals(x.categoryId))n++;return n;}
  void chooseVodCategory(boolean series,Button button,BaseAdapter a,TextView state){ArrayList<String> names=new ArrayList<>();names.add("Todas");names.add("Continuar viendo");names.add("Favoritos");for(String n:(series?seriesCategories:vodCategories).values())names.add(n);String[] labels=new String[names.size()];for(int i=0;i<names.size();i++)labels[i]=names.get(i)+" ("+countVodCategory(series,names.get(i))+")";AlertDialog d=new AlertDialog.Builder(this).setTitle("Categoría").setItems(labels,(x,w)->{if(series)seriesCategory=names.get(w);else vodCategory=names.get(w);button.setText(names.get(w));filterVod(series);a.notifyDataSetChanged();state.setText((series?seriesShown:vodShown).size()+" resultados");}).setNegativeButton("Cerrar",null).create();styleDialog(d);}
  void chooseVodSort(boolean series,BaseAdapter a,TextView state){String[] opts={"Añadidos recientes","A-Z","Z-A","Año"};AlertDialog d=new AlertDialog.Builder(this).setTitle("Ordenar").setItems(opts,(x,w)->{if(series)seriesSort=opts[w];else vodSort=opts[w];filterVod(series);a.notifyDataSetChanged();state.setText((series?seriesShown:vodShown).size()+" resultados · "+opts[w]);}).setNegativeButton("Cerrar",null).create();styleDialog(d);}

  final class VodGridAdapter extends BaseAdapter{final List<VodItem> data;final boolean series;VodGridAdapter(List<VodItem>d,boolean s){data=d;series=s;}public int getCount(){return data.size();}public VodItem getItem(int p){return data.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){VodItem x=getItem(p);LinearLayout card=old instanceof LinearLayout?(LinearLayout)old:new LinearLayout(MainActivity.this);card.removeAllViews();card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(4),dp(5),dp(4),dp(5));card.setBackground(glassCard());ImageView poster=new ImageView(MainActivity.this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(poster,new LinearLayout.LayoutParams(-1,dp(getResources().getConfiguration().screenWidthDp<430?155:185)));TextView n=tv(x.name,12,Color.WHITE);n.setTypeface(Typeface.DEFAULT,Typeface.BOLD);n.setGravity(Gravity.CENTER);n.setMaxLines(2);n.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(n,new LinearLayout.LayoutParams(-1,dp(38)));String mark=(series?seriesFavorites:vodFavorites).contains(x.id)?"★ ":"";String meta=mark+(series&&hasSeriesResume(x.id)?"Continuar · ":(!series&&hasMediaResume("movie",x.id)?"Continuar · ":""))+(x.year.isEmpty()?x.rating:x.year+(x.rating.isEmpty()?"":" · "+x.rating));TextView m=tv(meta,10,CYAN);m.setGravity(Gravity.CENTER);m.setSingleLine(true);card.addView(m,new LinearLayout.LayoutParams(-1,dp(23)));bindPoster(poster,x.poster,x.id);card.setFocusable(true);return card;}}

  void bindPoster(ImageView iv,String url,String identity){String key=url==null?"":url.trim();iv.setTag(identity);Bitmap mem=key.isEmpty()?null:posterCache.get(key);if(mem!=null){iv.setImageBitmap(mem);return;}iv.setImageResource(R.drawable.pv_logo);if(key.isEmpty()||!posterLoading.add(key))return;imageIo.submit(()->{Bitmap bmp=null;File dir=new File(getCacheDir(),"pv_posters");if(!dir.exists())dir.mkdirs();File f=new File(dir,sha1(key)+".img");try{if(f.isFile()&&f.length()>0&&f.length()<3*1024*1024)bmp=BitmapFactory.decodeFile(f.getAbsolutePath());if(bmp==null){URLConnection cn=new URL(key).openConnection();cn.setConnectTimeout(4500);cn.setReadTimeout(7000);cn.setRequestProperty("User-Agent","PalmaVision/2.4.0");try(InputStream in=cn.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1&&total<3*1024*1024){out.write(b,0,n);total+=n;}byte[] raw=out.toByteArray();bmp=BitmapFactory.decodeByteArray(raw,0,raw.length);if(bmp!=null)try(FileOutputStream fo=new FileOutputStream(f)){fo.write(raw);}}}if(bmp!=null){int max=420,w=bmp.getWidth(),h=bmp.getHeight();if(w>max||h>max){float sc=Math.min((float)max/w,(float)max/h);Bitmap small=Bitmap.createScaledBitmap(bmp,Math.max(1,Math.round(w*sc)),Math.max(1,Math.round(h*sc)),true);if(small!=bmp)bmp.recycle();bmp=small;}}}catch(Exception ignored){}finally{posterLoading.remove(key);}if(bmp!=null){posterCache.put(key,bmp);final Bitmap ready=bmp;mainHandler.post(()->{if(identity.equals(iv.getTag()))iv.setImageBitmap(ready);});}});}

  SharedPreferences mediaProgress(){return getSharedPreferences("pv_media_progress",MODE_PRIVATE);}
  String mediaKey(String kind,String id){return kind+"_"+id;}
  long mediaPosition(String kind,String id){return mediaProgress().getLong("pos_"+mediaKey(kind,id),0L);}
  boolean hasMediaResume(String kind,String id){SharedPreferences p=mediaProgress();return CachePolicy.shouldResume(p.getLong("pos_"+mediaKey(kind,id),0L),p.getLong("dur_"+mediaKey(kind,id),0L));}
  boolean hasSeriesResume(String seriesId){String ep=mediaProgress().getString("series_last_"+seriesId,"");return !ep.isEmpty()&&hasMediaResume("episode",ep);}
  void clearMediaProgress(String kind,String id){mediaProgress().edit().remove("pos_"+mediaKey(kind,id)).remove("dur_"+mediaKey(kind,id)).apply();}
  void saveVodProgress(){if(currentVod==null||vodPlayer==null)return;long pos=Math.max(0,vodPlayer.getCurrentPosition()),dur=Math.max(0,vodPlayer.getDuration());if(dur>0&&pos>=dur-120000L){clearMediaProgress(currentVod.kind,currentVod.id);return;}SharedPreferences.Editor e=mediaProgress().edit().putLong("pos_"+mediaKey(currentVod.kind,currentVod.id),pos).putLong("dur_"+mediaKey(currentVod.kind,currentVod.id),dur).putString("title_"+mediaKey(currentVod.kind,currentVod.id),currentVod.title).putString("poster_"+mediaKey(currentVod.kind,currentVod.id),currentVod.poster);if("episode".equals(currentVod.kind)){e.putString("series_last_"+currentVod.parentId,currentVod.id).putInt("series_season_"+currentVod.parentId,currentVod.season).putInt("series_episode_"+currentVod.parentId,currentVod.episode);}e.apply();vodLastSavedAt=SystemClock.elapsedRealtime();}

  void showMovieDetail(VodItem item){setPage("moviedetail","Película");LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(10),dp(8),dp(10),dp(10));p.setBackground(outlinePanel());contentFrame.addView(p,new FrameLayout.LayoutParams(-1,-1));boolean wide=getResources().getConfiguration().screenWidthDp>=650;LinearLayout top=new LinearLayout(this);top.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);ImageView poster=new ImageView(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);top.addView(poster,new LinearLayout.LayoutParams(wide?dp(210):-1,wide?dp(310):dp(260)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),dp(4),dp(8),dp(4));TextView title=tv(item.name,22,Color.WHITE);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);TextView meta=tv((item.year.isEmpty()?"":item.year)+(item.rating.isEmpty()?"":" · ★ "+item.rating),12,CYAN);TextView plot=tv("Cargando información…",13,MUTED);plot.setTag("movie_plot");plot.setMaxLines(8);info.addView(title,new LinearLayout.LayoutParams(-1,dp(42)));info.addView(meta,new LinearLayout.LayoutParams(-1,dp(28)));info.addView(plot,new LinearLayout.LayoutParams(-1,0,1));top.addView(info,new LinearLayout.LayoutParams(wide?0:-1,wide?dp(310):dp(220),wide?1:0));p.addView(top,new LinearLayout.LayoutParams(-1,wide?dp(315):dp(490)));bindPoster(poster,item.poster,item.id+"detail");long pos=mediaPosition("movie",item.id);boolean resume=hasMediaResume("movie",item.id);LinearLayout acts=new LinearLayout(this);Button play=primaryIconBtn(resume?"Continuar · "+formatClock(pos):"Reproducir",R.drawable.pv_ic_next),start=iconBtn("Desde el inicio",R.drawable.pv_ic_refresh),fav=iconBtn(vodFavorites.contains(item.id)?"Guardada":"Favorito",R.drawable.pv_ic_star);acts.addView(play,weight());acts.addView(start,weight());acts.addView(fav,weight());p.addView(acts,new LinearLayout.LayoutParams(-1,dp(58)));play.setOnClickListener(v->playMovie(item,resume?pos:0));start.setOnClickListener(v->playMovie(item,0));fav.setOnClickListener(v->{if(!vodFavorites.add(item.id))vodFavorites.remove(item.id);savePrefs();showMovieDetail(item);});loadMovieInfo(item);}
  void loadMovieInfo(VodItem item){String key=providerCacheIdentity("vodinfo_"+item.id),url=xtreamApiUrl("get_vod_info","vod_id="+Uri.encode(item.id));catalogIo.submit(()->{String raw=readJsonCache(key,2*1024*1024);if(raw!=null)applyMovieInfo(raw);try{String n=jsonText(url,2*1024*1024);new JSONObject(n);writeJsonCache(key,n);applyMovieInfo(n);}catch(Exception ignored){}});}
  void applyMovieInfo(String raw){try{JSONObject root=new JSONObject(raw),i=root.optJSONObject("info");if(i==null)i=root;String plot=i.optString("plot",i.optString("description","Sin descripción disponible."));String genre=i.optString("genre","");String duration=i.optString("duration","");String released=i.optString("releasedate",i.optString("releaseDate",""));final String text=(genre.isEmpty()?"":genre+"\n")+(duration.isEmpty()?"":duration+(released.isEmpty()?"":" · "+released)+"\n\n")+plot;mainHandler.post(()->{View v=findTagged(contentFrame,"movie_plot");if(v instanceof TextView)((TextView)v).setText(text);});}catch(Exception ignored){}}
