  void showSeriesEpisodes(VodItem series){lastSeriesId=series.id;setPage("seriesepisodes","Serie");LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(10),dp(7),dp(10),dp(10));p.setBackground(outlinePanel());contentFrame.addView(p,new FrameLayout.LayoutParams(-1,-1));LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);ImageView poster=new ImageView(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);head.addView(poster,new LinearLayout.LayoutParams(dp(92),dp(128)));LinearLayout hb=new LinearLayout(this);hb.setOrientation(LinearLayout.VERTICAL);hb.setPadding(dp(12),0,0,0);TextView n=tv(series.name,20,Color.WHITE);n.setTypeface(Typeface.DEFAULT,Typeface.BOLD);TextView st=tv("Cargando temporadas y episodios…",11,CYAN);st.setTag("series_state");Button fav=iconBtn(seriesFavorites.contains(series.id)?"Guardada":"Favorito",R.drawable.pv_ic_star);hb.addView(n,new LinearLayout.LayoutParams(-1,dp(40)));hb.addView(st,new LinearLayout.LayoutParams(-1,dp(30)));hb.addView(fav,new LinearLayout.LayoutParams(dp(130),dp(46)));head.addView(hb,new LinearLayout.LayoutParams(0,dp(128),1));p.addView(head,new LinearLayout.LayoutParams(-1,dp(132)));bindPoster(poster,series.poster,series.id+"seriesdetail");LinearLayout holder=new LinearLayout(this);holder.setOrientation(LinearLayout.VERTICAL);holder.setTag("series_holder");p.addView(holder,new LinearLayout.LayoutParams(-1,0,1));fav.setOnClickListener(v->{if(!seriesFavorites.add(series.id))seriesFavorites.remove(series.id);savePrefs();showSeriesEpisodes(series);});loadSeriesInfo(series);}
  void loadSeriesInfo(VodItem series){String key=providerCacheIdentity("seriesinfo_"+series.id),url=xtreamApiUrl("get_series_info","series_id="+Uri.encode(series.id));catalogIo.submit(()->{String cached=readJsonCache(key,16*1024*1024);if(cached!=null){SeriesPayload p=parseSeriesInfo(cached,series);if(!p.episodes.isEmpty())mainHandler.post(()->renderSeriesInfo(series,p,true));}try{String raw=jsonText(url,16*1024*1024);SeriesPayload p=parseSeriesInfo(raw,series);if(p.episodes.isEmpty())throw new IOException("Sin episodios");writeJsonCache(key,raw);mainHandler.post(()->renderSeriesInfo(series,p,false));}catch(Exception ex){mainHandler.post(()->{View v=findTagged(contentFrame,"series_state");if(v instanceof TextView)((TextView)v).setText("No se pudo actualizar · se conserva la copia local");});}});}
  SeriesPayload parseSeriesInfo(String raw,VodItem series){SeriesPayload out=new SeriesPayload();try{JSONObject root=new JSONObject(raw),info=root.optJSONObject("info");if(info!=null)out.plot=info.optString("plot",info.optString("description",""));JSONObject eps=root.optJSONObject("episodes");if(eps!=null){Iterator<String> it=eps.keys();while(it.hasNext()){String sk=it.next();JSONArray arr=eps.optJSONArray(sk);if(arr==null)continue;int seasonNum=parseInt(sk,0);for(int i=0;i<arr.length();i++){JSONObject e=arr.optJSONObject(i);if(e==null)continue;String id=e.optString("id",e.optString("stream_id",""));if(id.isEmpty())continue;int ep=e.optInt("episode_num",i+1);String title=e.optString("title","Episodio "+ep);String ext=e.optString("container_extension","mp4");JSONObject ei=e.optJSONObject("info");String duration=ei==null?"":ei.optString("duration","");out.episodes.add(new SeriesEpisode(id,title,ext,seasonNum,ep,duration));}}}}catch(Exception ignored){}Collections.sort(out.episodes,(a,b)->a.season==b.season?Integer.compare(a.episode,b.episode):Integer.compare(a.season,b.season));return out;}
  int parseInt(String s,int d){try{return Integer.parseInt(s);}catch(Exception e){return d;}}
  void renderSeriesInfo(VodItem series,SeriesPayload payload,boolean cached){if(!"seriesepisodes".equals(page)||!series.id.equals(lastSeriesId))return;View sv=findTagged(contentFrame,"series_state");if(sv instanceof TextView)((TextView)sv).setText((cached?"Copia local · ":"")+payload.episodes.size()+" episodios");View hv=findTagged(contentFrame,"series_holder");if(!(hv instanceof LinearLayout))return;LinearLayout holder=(LinearLayout)hv;holder.removeAllViews();TreeMap<Integer,List<SeriesEpisode>> seasons=new TreeMap<>();for(SeriesEpisode e:payload.episodes){List<SeriesEpisode> list=seasons.get(e.season);if(list==null){list=new ArrayList<>();seasons.put(e.season,list);}list.add(e);}if(seasons.isEmpty())return;ArrayList<Integer> seasonNums=new ArrayList<>(seasons.keySet());int initial=seasonNums.get(0);int saved=mediaProgress().getInt("series_season_"+series.id,initial);if(seasons.containsKey(saved))initial=saved;Button choose=iconBtn("Temporada "+initial,R.drawable.pv_ic_grid);holder.addView(choose,new LinearLayout.LayoutParams(-1,dp(50)));ListView lv=new ListView(this);holder.addView(lv,new LinearLayout.LayoutParams(-1,0,1));final int[] selected={initial};Runnable draw=()->{List<SeriesEpisode> data=seasons.get(selected[0]);BaseAdapter a=new BaseAdapter(){public int getCount(){return data==null?0:data.size();}public SeriesEpisode getItem(int p){return data.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){SeriesEpisode e=getItem(p);LinearLayout row=new LinearLayout(MainActivity.this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(12),dp(7),dp(12),dp(7));row.setBackground(rounded(Color.argb(232,6,29,50),12));TextView t=tv("E"+e.episode+" · "+e.title,14,Color.WHITE);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);TextView m=tv((hasMediaResume("episode",e.id)?"Continuar · "+formatClock(mediaPosition("episode",e.id)):"Reproducir")+(e.duration.isEmpty()?"":" · "+e.duration),11,CYAN);row.addView(t,new LinearLayout.LayoutParams(-1,dp(27)));row.addView(m,new LinearLayout.LayoutParams(-1,dp(22)));return row;}};lv.setAdapter(a);lv.setDivider(new ColorDrawable(Color.TRANSPARENT));lv.setDividerHeight(dp(5));lv.setOnItemClickListener((x,v,pos,id)->{SeriesEpisode e=data.get(pos);long start=hasMediaResume("episode",e.id)?mediaPosition("episode",e.id):0;playEpisode(series,e,start);});};draw.run();choose.setOnClickListener(v->{String[] labels=new String[seasonNums.size()];for(int i=0;i<labels.length;i++)labels[i]="Temporada "+seasonNums.get(i);AlertDialog d=new AlertDialog.Builder(this).setTitle("Temporada").setItems(labels,(x,w)->{selected[0]=seasonNums.get(w);choose.setText(labels[w]);draw.run();}).setNegativeButton("Cerrar",null).create();styleDialog(d);});}
  void playEpisode(VodItem series,SeriesEpisode e,long position){VodPlayback v=new VodPlayback("episode",e.id,series.id,series.name+" · T"+e.season+" E"+e.episode+" · "+e.title,xtreamStreamUrl("series",e.id,e.container),series.poster,e.season,e.episode);vodReturn="series:"+series.id;startVodPlayback(v,position);}
