  void ensureVodPlayer(){if(vodPlayer!=null)return;vodPlayer=new ExoPlayer.Builder(this).build();applyLanguagePrefs(vodPlayer,null);vodPlayer.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int s){if(s==Player.STATE_READY){vodRetries=0;if(vodStatus!=null)vodStatus.setText("Reproduciendo · usa −10 / +10 o arrastra la línea de tiempo");}else if(s==Player.STATE_BUFFERING){if(vodStatus!=null)vodStatus.setText(vodRetries>0?"Reconectando "+vodRetries+"/3 desde "+formatClock(vodPendingResume):"Cargando…");}else if(s==Player.STATE_ENDED){saveVodProgress();if(currentVod!=null)clearMediaProgress(currentVod.kind,currentVod.id);if(vodStatus!=null)vodStatus.setText("Finalizado");}}@Override public void onPlayerError(PlaybackException e){long pos=Math.max(vodPendingResume,vodPlayer.getCurrentPosition());vodPendingResume=pos;if(vodRetries<3){vodRetries++;if(vodStatus!=null)vodStatus.setText("Reconectando "+vodRetries+"/3 desde "+formatClock(pos));mainHandler.postDelayed(()->prepareVodAt(pos),700L+vodRetries*650L);}else if(vodStatus!=null)vodStatus.setText("No se pudo recuperar la reproducción");}});}
  void startVodPlayback(VodPlayback ctx,long start){pauseRadioForOtherMedia();if(player!=null)player.pause();currentVod=ctx;vodPendingResume=Math.max(0,start);vodRetries=0;ensureVodPlayer();showVodPlayer();prepareVodAt(vodPendingResume);}
  void prepareVodAt(long pos){if(currentVod==null||vodPlayer==null)return;try{MediaItem item=new MediaItem.Builder().setUri(currentVod.url).setMediaId(currentVod.id).setMediaMetadata(new MediaMetadata.Builder().setTitle(currentVod.title).build()).build();vodPlayer.setMediaItem(item);vodPlayer.prepare();if(pos>0)vodPlayer.seekTo(pos);vodPlayer.play();vodPendingResume=pos;}catch(Exception e){if(vodStatus!=null)vodStatus.setText("Error al abrir contenido");}}
  void showVodPlayer(){setPage("vodplayer","Reproducción");LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(7),dp(5),dp(7),dp(7));p.setBackground(outlinePanel());contentFrame.addView(p,new FrameLayout.LayoutParams(-1,-1));TextView title=tv(currentVod==null?"Reproducción":currentVod.title,17,Color.WHITE);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);p.addView(title,new LinearLayout.LayoutParams(-1,dp(38)));vodStatus=tv("Preparando…",11,CYAN);p.addView(vodStatus,new LinearLayout.LayoutParams(-1,dp(25)));vodPlayerView=new PlayerView(this);vodPlayerView.setUseController(true);vodPlayerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);vodPlayerView.setPlayer(vodPlayer);vodPlayerView.setFocusable(true);p.addView(vodPlayerView,new LinearLayout.LayoutParams(-1,0,1));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);Button back=controlBtn("−10 s",R.drawable.pv_ic_prev),pause=controlBtn("Pausa / Play",R.drawable.pv_ic_next),fwd=controlBtn("+10 s",R.drawable.pv_ic_next),tracks=controlBtn("Audio / Subtítulos",R.drawable.pv_ic_audio),full=controlBtn("Pantalla",R.drawable.pv_ic_fullscreen);for(Button b:new Button[]{back,pause,fwd,tracks,full})row.addView(b,weight());p.addView(row,new LinearLayout.LayoutParams(-1,dp(54)));vodClock=tv("00:00 / --:--",11,MUTED);vodClock.setGravity(Gravity.CENTER);p.addView(vodClock,new LinearLayout.LayoutParams(-1,dp(26)));back.setOnClickListener(v->seekVodBy(-10000));fwd.setOnClickListener(v->seekVodBy(10000));pause.setOnClickListener(v->toggleVodPlay());tracks.setOnClickListener(v->showVodTrackMenu());full.setOnClickListener(v->openVodFullscreen());startVodProgressLoop();}
  void startVodProgressLoop(){if(vodProgressTask!=null)mainHandler.removeCallbacks(vodProgressTask);vodProgressTask=new Runnable(){public void run(){if(vodPlayer==null||currentVod==null)return;long pos=Math.max(0,vodPlayer.getCurrentPosition()),dur=Math.max(0,vodPlayer.getDuration());if(vodClock!=null)vodClock.setText(formatClock(pos)+" / "+(dur>0?formatClock(dur):"--:--"));if(SystemClock.elapsedRealtime()-vodLastSavedAt>=10000L)saveVodProgress();mainHandler.postDelayed(this,1000L);}};mainHandler.post(vodProgressTask);}
  void seekVodBy(long delta){if(vodPlayer==null)return;long pos=Math.max(0,vodPlayer.getCurrentPosition()+delta),dur=vodPlayer.getDuration();if(dur>0)pos=Math.min(pos,Math.max(0,dur-1000));vodPendingResume=pos;vodPlayer.seekTo(pos);if(vodStatus!=null)vodStatus.setText((delta<0?"Retrocediendo a ":"Avanzando a ")+formatClock(pos));saveVodProgress();}
