  String formatClock(long ms){long sec=Math.max(0,ms/1000),h=sec/3600,m=(sec%3600)/60,s=sec%60;return h>0?String.format(Locale.ROOT,"%d:%02d:%02d",h,m,s):String.format(Locale.ROOT,"%02d:%02d",m,s);}
