  void saveEpgCache(String url,Map<String,List<Program>> schedules){try{JSONObject root=new JSONObject();root.put("saved_at",System.currentTimeMillis());JSONObject chans=new JSONObject();for(Map.Entry<String,List<Program>> e:schedules.entrySet()){JSONArray a=new JSONArray();int n=0;for(Program p:e.getValue()){if(n++>=256)break;JSONObject x=new JSONObject();x.put("t",p.title);x.put("s",p.start);x.put("e",p.stop);a.put(x);}if(a.length()>0)chans.put(e.getKey(),a);}root.put("channels",chans);writeJsonCache(safeCacheKey("epg",url),root.toString());getSharedPreferences("tvplus",MODE_PRIVATE).edit().putLong("epg_cache_time_"+sha1(url),System.currentTimeMillis()).apply();}catch(Exception ignored){}}
  void restoreEpgCache(String url,String label,long generation,int total){String raw=readJsonCache(safeCacheKey("epg",url),32*1024*1024);if(raw==null)return;try{JSONObject root=new JSONObject(raw),chans=root.optJSONObject("channels");if(chans==null)return;ConcurrentHashMap<String,List<Program>> schedules=new ConcurrentHashMap<>();ConcurrentHashMap<String,Program> fresh=new ConcurrentHashMap<>();long now=System.currentTimeMillis();Iterator<String> it=chans.keys();while(it.hasNext()){String id=it.next();JSONArray a=chans.optJSONArray(id);if(a==null)continue;ArrayList<Program> list=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;Program pr=new Program(x.optString("t","Programa"),x.optLong("s",0),x.optLong("e",0));if(pr.start>0&&pr.stop>0){list.add(pr);if(now>=pr.start&&now<pr.stop)fresh.put(id,pr);}}if(!list.isEmpty())schedules.put(id,list);}if(schedules.isEmpty())return;long saved=root.optLong("saved_at",0);mainHandler.post(()->{if(generation!=epgGeneration)return;currentPrograms.clear();currentPrograms.putAll(fresh);programGuide.clear();programGuide.putAll(schedules);activeEpgLabel="EPG local · "+schedules.size()+"/"+total+" canales · "+ageLabel(saved);if(adapter!=null)adapter.notifyDataSetChanged();});}catch(Exception ignored){}}
  String ageLabel(long when){if(when<=0)return "copia guardada";long m=Math.max(0,(System.currentTimeMillis()-when)/60000L);if(m<60)return "hace "+m+" min";long h=m/60;if(h<48)return "hace "+h+" h";return "hace "+(h/24)+" días";}


  static final Pattern GROUP=Pattern.compile("group-title=\\\"([^\\\"]*)\\\""),ID=Pattern.compile("tvg-id=\\\"([^\\\"]*)\\\""),LOGO=Pattern.compile("tvg-logo=\\\"([^\\\"]*)\\\""),EPG=Pattern.compile("(?:x-tvg-url|url-tvg)=\\\"([^\\\"]+)\\\"",Pattern.CASE_INSENSITIVE),SCORE=Pattern.compile("nexus-score=\\\"?(\\d+)\\\"?");
  List<Channel> parse(InputStream in)throws IOException{ArrayList<Channel> out=new ArrayList<>();if(in==null)return out;String epg="";try(BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String line,meta=null;while((line=br.readLine())!=null){line=line.replace("\uFEFF","").trim();if(line.startsWith("#EXTM3U")){Matcher em=EPG.matcher(line);if(em.find())epg=em.group(1).trim();continue;}if(line.startsWith("#EXTINF:"))meta=line;else if(!line.isEmpty()&&!line.startsWith("#")&&meta!=null){String name=meta.contains(",")?meta.substring(meta.lastIndexOf(',')+1).trim():"Canal";Matcher gm=GROUP.matcher(meta),im=ID.matcher(meta),lm=LOGO.matcher(meta),sm=SCORE.matcher(meta);String group=gm.find()?gm.group(1):"Otros";String id=im.find()&&im.group(1).trim().length()>0?im.group(1):sha1(name+"|"+line);String logo=lm.find()?lm.group(1).trim():"";int score=sm.find()?Integer.parseInt(sm.group(1)):0;out.add(new Channel(id,name,group,line,logo,score));meta=null;}}}detectedPlaylistEpgUrl=epg;return out;}

  static String sha1(String s){try{byte[] b=MessageDigest.getInstance("SHA-1").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder x=new StringBuilder();for(byte v:b)x.append(String.format("%02x",v));return x.toString();}catch(Exception e){return Integer.toHexString(s.hashCode());}}
